CREATE OR REPLACE FUNCTION "private"."apply_lead_action_fact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
declare
  cycle_assigned_at timestamptz;
begin
  if new.qualifies_first_outreach and not new.is_automated and new.assignment_cycle_id is not null then
    update public.lead_assignment_cycles
    set first_human_outreach_at = coalesce(first_human_outreach_at, new.occurred_at)
    where id = new.assignment_cycle_id
    returning assigned_at into cycle_assigned_at;

    update public.leads
    set first_response_at = new.occurred_at,
        first_response_seconds = greatest(0, extract(epoch from (new.occurred_at - coalesce(cycle_assigned_at, created_at)))::integer),
        first_response_channel = new.channel,
        first_response_is_automation = false,
        first_response_actor_user_id = new.actor_user_id,
        last_contact_at = greatest(coalesce(last_contact_at, new.occurred_at), new.occurred_at),
        updated_at = now()
    where id = new.lead_id
      and organization_id = new.organization_id
      and first_response_at is null;
  elsif new.qualifies_stage_inactivity then
    update public.leads
    set last_contact_at = greatest(coalesce(last_contact_at, new.occurred_at), new.occurred_at),
        updated_at = now()
    where id = new.lead_id and organization_id = new.organization_id;
  end if;

  if new.is_effective_contact and new.assignment_cycle_id is not null then
    update public.lead_assignment_cycles
    set first_effective_contact_at = coalesce(first_effective_contact_at, new.occurred_at)
    where id = new.assignment_cycle_id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."apply_lead_action_fact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."attention_metadata_is_automated"("value" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
  select
    lower(coalesce(value->>'is_automation', value->>'is_automated', value->>'automated', 'false')) in ('true', '1', 'yes')
    or lower(btrim(coalesce(value->>'origin', ''))) in (
      'ai', 'openai', 'automation', 'bot', 'ai_autoreply', 'ai_followup'
    )
    or lower(btrim(coalesce(value->>'origin', ''))) ~ '^(ai|automation)[_.]'
    or lower(coalesce(value->>'sender_type', '')) in ('ai', 'automation', 'bot');
$$;


ALTER FUNCTION "private"."attention_metadata_is_automated"("value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."audit_jsonb_diff"("p_old" "jsonb", "p_new" "jsonb", "p_excluded_columns" "text"[] DEFAULT ARRAY[]::"text"[]) RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with keys(key) as (
    select jsonb_object_keys(coalesce(p_old, '{}'::jsonb))
    union
    select jsonb_object_keys(coalesce(p_new, '{}'::jsonb))
  )
  select coalesce(
    jsonb_object_agg(
      key,
      jsonb_build_object('old', p_old -> key, 'new', p_new -> key)
      order by key
    ),
    '{}'::jsonb
  )
  from keys
  where not (key = any(p_excluded_columns))
    and (p_old -> key) is distinct from (p_new -> key);
$$;


ALTER FUNCTION "private"."audit_jsonb_diff"("p_old" "jsonb", "p_new" "jsonb", "p_excluded_columns" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."automation_assign_lead_user"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_user_id" "uuid", "p_actor_user_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  previous_user_id uuid;
  lead_team_id uuid;
  lead_name text;
  target_user_name text;
begin
  if p_user_id is null then
    raise exception 'automation_assignee_required';
  end if;

  select l.assigned_user_id, l.team_id, coalesce(nullif(l.name, ''), 'Lead')
  into previous_user_id, lead_team_id, lead_name
  from public.leads l
  where l.organization_id = p_organization_id and l.id = p_lead_id
  for update;
  if not found then
    raise exception 'automation_target_lead_not_found';
  end if;

  select coalesce(nullif(u.name, ''), nullif(u.email, ''), 'Usuario')
  into target_user_name
  from public.organization_members om
  join public.users u on u.id = om.user_id and coalesce(u.is_active, true) = true
  where om.organization_id = p_organization_id
    and om.user_id = p_user_id
    and coalesce(om.is_active, true) = true;
  if target_user_name is null then
    raise exception 'automation_assignee_not_active_in_organization';
  end if;

  if lead_team_id is not null and not exists (
    select 1 from public.team_members tm
    where tm.organization_id = p_organization_id
      and tm.team_id = lead_team_id
      and tm.user_id = p_user_id
      and coalesce(tm.is_active, true) = true
  ) then
    raise exception 'automation_assignee_not_in_lead_team';
  end if;

  if previous_user_id is distinct from p_user_id then
    update public.leads
    set assigned_user_id = p_user_id,
        assigned_at = now(),
        updated_at = now()
    where organization_id = p_organization_id and id = p_lead_id;

    insert into public.assignments_log (
      organization_id, lead_id, old_user_id, new_user_id, reason, created_by
    ) values (
      p_organization_id, p_lead_id, previous_user_id, p_user_id,
      'automation_assignment', p_actor_user_id
    );

    perform private.notify_automation_attention(
      p_organization_id,
      p_lead_id,
      p_user_id,
      'Lead atribuido para voce',
      lead_name || ' foi atribuido por uma automacao.',
      'automation_lead_assigned',
      'automation-assignment:' || p_execution_id::text || ':' || p_node_key,
      jsonb_build_object(
        'execution_id', p_execution_id,
        'node_key', p_node_key,
        'previous_user_id', previous_user_id,
        'assigned_user_id', p_user_id
      )
    );
  end if;

  return jsonb_build_object(
    'assignment_changed', previous_user_id is distinct from p_user_id,
    'previous_user_id', previous_user_id,
    'assigned_user_id', p_user_id,
    'assigned_user_name', target_user_name
  );
end;
$$;


ALTER FUNCTION "private"."automation_assign_lead_user"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_user_id" "uuid", "p_actor_user_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."automation_move_lead_stage"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_stage_id" "uuid", "p_pipeline_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  destination record;
  previous_stage_id uuid;
  previous_pipeline_id uuid;
begin
  select s.id, s.pipeline_id, s.name
  into destination
  from public.stages s
  join public.pipelines p
    on p.id = s.pipeline_id
   and p.organization_id = s.organization_id
   and p.is_active = true
  where s.organization_id = p_organization_id
    and s.id = p_stage_id
    and s.is_active = true
    and (p_pipeline_id is null or s.pipeline_id = p_pipeline_id)
  limit 1;

  if destination.id is null then
    raise exception 'automation_destination_stage_invalid';
  end if;

  select l.stage_id, l.pipeline_id
  into previous_stage_id, previous_pipeline_id
  from public.leads l
  where l.organization_id = p_organization_id and l.id = p_lead_id
  for update;

  if not found then
    raise exception 'automation_target_lead_not_found';
  end if;

  update public.leads l
  set stage_id = destination.id,
      pipeline_id = destination.pipeline_id,
      stage_entered_at = case
        when l.stage_id is distinct from destination.id or l.pipeline_id is distinct from destination.pipeline_id
          then now()
        else l.stage_entered_at
      end,
      board_order_at = case
        when l.stage_id is distinct from destination.id or l.pipeline_id is distinct from destination.pipeline_id
          then now()
        else l.board_order_at
      end,
      updated_at = now()
  where l.organization_id = p_organization_id and l.id = p_lead_id;

  return jsonb_build_object(
    'stage_changed', previous_stage_id is distinct from destination.id
      or previous_pipeline_id is distinct from destination.pipeline_id,
    'from_stage_id', previous_stage_id,
    'from_pipeline_id', previous_pipeline_id,
    'to_stage_id', destination.id,
    'to_pipeline_id', destination.pipeline_id,
    'to_stage_name', destination.name
  );
end;
$$;


ALTER FUNCTION "private"."automation_move_lead_stage"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_stage_id" "uuid", "p_pipeline_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."broadcast_audit_log_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.organization_id is null then
    return null;
  end if;

  begin
    perform realtime.send(
      jsonb_build_object(
        'auditId', new.id,
        'organizationId', new.organization_id,
        'actorUserId', new.user_id,
        'action', new.action,
        'entityType', new.entity_type,
        'entityId', new.entity_id,
        'createdAt', new.created_at
      ),
      'audit.log.created',
      'audit:' || new.organization_id::text || ':feed',
      true
    );
  exception when others then
    return null;
  end;

  return null;
end;
$$;


ALTER FUNCTION "private"."broadcast_audit_log_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."broadcast_whatsapp_message_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  message_row public.whatsapp_messages;
begin
  message_row := case when tg_op = 'DELETE' then old else new end;
  if message_row.lead_id is null then
    return null;
  end if;

  begin
    insert into realtime.messages (payload, event, topic, private, extension)
    values (
      jsonb_build_object('scope', 'conversations'),
      'whatsapp.inbox.changed',
      'whatsapp:' || message_row.organization_id::text || ':inbox',
      true,
      'broadcast'
    );

    perform realtime.send(
      jsonb_build_object(
        'operation', tg_op,
        'messageId', message_row.id,
        'conversationId', message_row.conversation_id,
        'clientMessageId', message_row.client_message_id,
        'status', message_row.status,
        'sentAt', message_row.sent_at
      ),
      'whatsapp.message.changed',
      'whatsapp:' || message_row.organization_id::text || ':lead:' || message_row.lead_id::text,
      true
    );
  exception when others then
    return null;
  end;
  return null;
end;
$$;


ALTER FUNCTION "private"."broadcast_whatsapp_message_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_access_lead"("target_organization_id" "uuid", "assigned_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and (
        private.has_permission(target_organization_id, 'lead_view_all')
        or assigned_user_id = (select auth.uid())
        or private.has_org_role(target_organization_id, array['owner', 'admin', 'manager'])
        or (
          assigned_user_id is not null
          and private.has_permission(target_organization_id, 'lead_view_team')
          and exists (
            select 1
            from public.team_members leader
            join public.team_members member
              on member.organization_id = leader.organization_id
             and member.team_id = leader.team_id
             and coalesce(member.is_active, false) = true
            where leader.organization_id = target_organization_id
              and leader.user_id = (select auth.uid())
              and coalesce(leader.is_active, false) = true
              and coalesce(leader.is_leader, false) = true
              and member.user_id = assigned_user_id
          )
        )
      )
    );
$$;


ALTER FUNCTION "private"."can_access_lead"("target_organization_id" "uuid", "assigned_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_access_lead_by_id"("p_lead_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_lead_org_id uuid;
  v_lead_assigned_to uuid;
  v_user_org_id uuid;
BEGIN
  SELECT l.organization_id, l.assigned_user_id
  INTO v_lead_org_id, v_lead_assigned_to
  FROM public.leads l
  WHERE l.id = p_lead_id;

  IF v_lead_org_id IS NULL THEN
    RETURN FALSE;
  END IF;

  SELECT u.organization_id INTO v_user_org_id
  FROM public.users u
  WHERE u.id = p_user_id;

  IF v_user_org_id IS NULL OR v_user_org_id != v_lead_org_id THEN
    RETURN FALSE;
  END IF;

  IF public.is_super_admin()
     OR public.is_admin()
     OR public.user_has_permission('lead_view_all', p_user_id)
     OR public.user_has_permission('lead_edit_all', p_user_id) THEN
    RETURN TRUE;
  END IF;

  IF v_lead_assigned_to = p_user_id THEN
    RETURN TRUE;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.team_members tm_leader
    JOIN public.team_members tm_assigned ON tm_assigned.team_id = tm_leader.team_id
    WHERE tm_leader.user_id = p_user_id
      AND tm_leader.is_leader = true
      AND tm_assigned.user_id = v_lead_assigned_to
  ) THEN
    RETURN TRUE;
  END IF;

  RETURN FALSE;
END;
$$;


ALTER FUNCTION "private"."can_access_lead_by_id"("p_lead_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_access_schedule_event"("p_event_id" "uuid", "p_require_full_details" boolean DEFAULT true) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  with ctx as (
    select
      auth.uid() as user_id,
      public.get_user_organization_id() as organization_id,
      public.is_admin() as is_admin,
      public.is_super_admin() as is_super_admin
  )
  select exists (
    select 1
    from public.schedule_events e
    cross join ctx
    where e.id = p_event_id
      and ctx.user_id is not null
      and (
        ctx.is_super_admin
        or (
          e.organization_id = ctx.organization_id
          and (
            case
              when p_require_full_details then
                coalesce(e.visibility, 'default') = 'default'
                or e.user_id = ctx.user_id
                or ctx.is_admin
                or public.is_schedule_event_assignee(e.id, ctx.user_id)
              else
                coalesce(e.visibility, 'default') in ('default', 'public')
                or e.user_id = ctx.user_id
                or ctx.is_admin
                or public.is_schedule_event_assignee(e.id, ctx.user_id)
            end
          )
        )
      )
  );
$$;


ALTER FUNCTION "private"."can_access_schedule_event"("p_event_id" "uuid", "p_require_full_details" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_manage_round_robin_as_leader"("p_round_robin_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.round_robins rr
    where rr.id = p_round_robin_id
      and rr.organization_id = public.get_user_organization_id()
      and rr.target_pipeline_id is not null
      and (
        (rr.created_by = p_user_id and public.is_team_leader(p_user_id))
        or public.is_pipeline_in_led_team(rr.target_pipeline_id, p_user_id)
        or exists (
          select 1
          from public.round_robin_members rrm
          where rrm.round_robin_id = rr.id
            and (
              (rrm.team_id is not null and public.is_user_leader_of_team(rrm.team_id, p_user_id))
              or (rrm.team_id is null and public.is_user_in_led_team(rrm.user_id, p_user_id))
            )
        )
      )
  );
$$;


ALTER FUNCTION "private"."can_manage_round_robin_as_leader"("p_round_robin_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_manage_whatsapp_session"("p_session_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.whatsapp_sessions ws
    where ws.id = p_session_id
      and (
        exists (
          select 1
          from public.users u
          where u.id = auth.uid()
            and u.role = 'super_admin'
            and coalesce(u.is_active, true) = true
        )
        or (
          private.is_org_member(ws.organization_id)
          and ws.owner_user_id = auth.uid()
        )
      )
  );
$$;


ALTER FUNCTION "private"."can_manage_whatsapp_session"("p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_receive_audit_broadcast"("p_topic" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  topic_organization_id uuid;
begin
  if split_part(p_topic, ':', 1) <> 'audit' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  if topic_organization_id is null then
    return false;
  end if;

  return p_topic = 'audit:' || topic_organization_id::text || ':feed'
    and private.has_org_role(topic_organization_id, array['owner', 'admin', 'manager']);
end;
$$;


ALTER FUNCTION "private"."can_receive_audit_broadcast"("p_topic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_receive_whatsapp_broadcast"("p_topic" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  topic_organization_id uuid;
  topic_lead_id uuid;
begin
  if split_part(p_topic, ':', 1) = 'audit' then
    return private.can_receive_audit_broadcast(p_topic);
  end if;

  if split_part(p_topic, ':', 1) <> 'whatsapp' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  if topic_organization_id is null then
    return false;
  end if;

  if split_part(p_topic, ':', 3) = 'inbox' then
    return p_topic = 'whatsapp:' || topic_organization_id::text || ':inbox'
      and private.is_org_member(topic_organization_id);
  end if;

  if split_part(p_topic, ':', 3) <> 'lead' then
    return false;
  end if;

  topic_lead_id := private.safe_uuid(split_part(p_topic, ':', 4));
  if topic_lead_id is null
     or p_topic <> 'whatsapp:' || topic_organization_id::text || ':lead:' || topic_lead_id::text then
    return false;
  end if;

  return exists (
    select 1
    from public.leads as lead
    where lead.id = topic_lead_id
      and lead.organization_id = topic_organization_id
      and private.can_access_lead(lead.organization_id, lead.assigned_user_id)
  );
end;
$$;


ALTER FUNCTION "private"."can_receive_whatsapp_broadcast"("p_topic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_track_public_site"("target_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select target_organization_id is not null
    and exists (
      select 1
      from public.organization_sites site
      join public.organizations organization
        on organization.id = site.organization_id
      where site.organization_id = target_organization_id
        and site.is_active = true
        and coalesce(organization.is_active, true) = true
    );
$$;


ALTER FUNCTION "private"."can_track_public_site"("target_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_use_organization_presence"("p_topic" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  topic_organization_id uuid;
begin
  if split_part(p_topic, ':', 1) <> 'presence' then
    return false;
  end if;

  topic_organization_id := private.safe_uuid(split_part(p_topic, ':', 2));
  if topic_organization_id is null then
    return false;
  end if;

  return p_topic = 'presence:' || topic_organization_id::text || ':online'
    and private.is_org_member(topic_organization_id);
end;
$$;


ALTER FUNCTION "private"."can_use_organization_presence"("p_topic" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."can_view_whatsapp_conversation"("p_conversation_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.whatsapp_conversations wc
    join public.whatsapp_sessions ws
      on ws.id = wc.session_id
     and ws.organization_id = wc.organization_id
    where wc.id = p_conversation_id
      and wc.deleted_at is null
      and public.vimob_can_access_whatsapp_session(wc.session_id, 'view')
  );
$$;


ALTER FUNCTION "private"."can_view_whatsapp_conversation"("p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."cancel_lead_automation_executions"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_reason" "text", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  cancelled_ids uuid[] := array[]::uuid[];
begin
  with cancelled as (
    update public.automation_executions e
    set status = 'cancelled',
        cancellation_requested_at = now(),
        completed_at = now(),
        error_message = left(coalesce(nullif(p_reason, ''), 'automation_handoff'), 4000),
        next_execution_at = null,
        locked_at = null,
        locked_by = null,
        updated_at = now()
    where e.organization_id = p_organization_id
      and e.lead_id = p_lead_id
      and e.status in ('queued', 'running', 'waiting')
      and (
        p_conversation_id is null
        or e.conversation_id is null
        or e.conversation_id = p_conversation_id
      )
    returning e.id
  ), closed_steps as (
    update public.automation_execution_steps s
    set status = 'cancelled',
        completed_at = now(),
        error_message = left(coalesce(nullif(p_reason, ''), 'automation_handoff'), 4000)
    where s.organization_id = p_organization_id
      and s.execution_id in (select id from cancelled)
      and s.status in ('running', 'waiting')
    returning s.id
  )
  select coalesce(array_agg(c.id), array[]::uuid[])
  into cancelled_ids
  from cancelled c;

  return cancelled_ids;
end;
$$;


ALTER FUNCTION "private"."cancel_lead_automation_executions"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_reason" "text", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."capture_activity_attention_fact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
declare
  normalized_type text := lower(btrim(coalesce(new.type, '')));
  automated boolean := private.attention_metadata_is_automated(new.metadata);
  outcome text := lower(btrim(coalesce(new.metadata->>'outcome', '')));
  qualifies_outreach boolean;
  qualifies_inactivity boolean;
  effective boolean;
begin
  qualifies_outreach := not automated and normalized_type in (
    'call', 'email', 'email_sent', 'message', 'whatsapp'
  );
  qualifies_inactivity := not automated and normalized_type in (
    'call', 'email', 'email_sent', 'message', 'whatsapp',
    'task_completed', 'feedback', 'feedback_added', 'note'
  );
  effective := outcome in (
    'efetivo', 'contato efetivo', 'connected', 'answered', 'atendeu', 'respondeu'
  );

  perform private.record_lead_action_fact(
    new.organization_id,
    new.lead_id,
    new.user_id,
    normalized_type,
    coalesce(new.metadata->>'channel', case when normalized_type like 'email%' then 'email' when normalized_type = 'call' then 'phone' else null end),
    new.created_at,
    automated,
    false,
    qualifies_outreach,
    qualifies_inactivity,
    effective,
    'activity',
    new.id::text,
    new.metadata || jsonb_build_object('content', new.content)
  );
  return null;
end;
$$;


ALTER FUNCTION "private"."capture_activity_attention_fact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."capture_automation_human_outbound_handoff"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  cancelled_ids uuid[];
  target_user_id uuid;
  target_lead_name text;
begin
  if coalesce(new.from_me, false) = false
     or new.direction <> 'outbound'
     or new.lead_id is null
     or coalesce(new.metadata->>'origin', '') = 'automation' then
    return new;
  end if;

  cancelled_ids := private.cancel_lead_automation_executions(
    new.organization_id,
    new.lead_id,
    'automation_handoff_human_outbound',
    null
  );

  if cardinality(cancelled_ids) > 0 then
    select l.assigned_user_id, l.name
    into target_user_id, target_lead_name
    from public.leads l
    where l.organization_id = new.organization_id and l.id = new.lead_id;

    perform private.notify_automation_attention(
      new.organization_id,
      new.lead_id,
      coalesce(target_user_id, new.sender_user_id),
      'Automacao interrompida pelo atendimento humano',
      coalesce(nullif(target_lead_name, ''), 'Lead') || ' agora esta em atendimento manual.',
      'automation_human_outbound',
      'automation_human_outbound:' || new.id::text || ':' || coalesce(target_user_id, new.sender_user_id)::text,
      jsonb_build_object(
        'message_id', new.id,
        'conversation_id', new.conversation_id,
        'execution_ids', to_jsonb(cancelled_ids)
      )
    );

    insert into public.lead_timeline_events (
      organization_id, lead_id, event_type, title, description,
      user_id, actor_user_id, metadata, event_at
    ) values (
      new.organization_id, new.lead_id,
      'automation_human_outbound',
      'Automacao interrompida por mensagem humana',
      left(coalesce(new.content, '[midia]'), 500),
      coalesce(new.sender_user_id, target_user_id),
      coalesce(new.sender_user_id, target_user_id),
      jsonb_build_object(
        'message_id', new.id,
        'conversation_id', new.conversation_id,
        'execution_ids', to_jsonb(cancelled_ids)
      ),
      coalesce(new.sent_at, new.created_at, now())
    );
  end if;

  return new;
exception when others then
  raise warning 'automation human outbound handoff failed: %', sqlerrm;
  return new;
end;
$$;


ALTER FUNCTION "private"."capture_automation_human_outbound_handoff"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."capture_automation_inbound_message_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if coalesce(new.from_me, false) = false
     and new.direction = 'inbound'
     and new.lead_id is not null then
    perform private.enqueue_automation_event(
      new.organization_id, 'message_received', 'whatsapp_message', new.id,
      new.lead_id, new.conversation_id,
      'message_received:' || new.id::text,
      jsonb_build_object(
        'message_id', new.id,
        'lead_id', new.lead_id,
        'conversation_id', new.conversation_id,
        'session_id', new.session_id,
        'message_type', coalesce(nullif(new.message_type, ''), 'text'),
        'content', new.content,
        'occurred_at', coalesce(new.received_at, new.created_at, now())
      )
    );
  end if;
  return new;
exception when others then
  raise warning 'automation message event enqueue failed: %', sqlerrm;
  return new;
end;
$$;


