ALTER TABLE "public"."whatsapp_webhook_inbox" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_webhook_inbox" IS 'Private durable WhatsApp webhook inbox. Raw payloads are retained temporarily for replay and must never be returned to CRM users.';



CREATE OR REPLACE FUNCTION "private"."claim_whatsapp_webhook_inbox"("p_worker_id" "text", "p_limit" integer DEFAULT 50, "p_lease" interval DEFAULT '00:05:00'::interval) RETURNS SETOF "public"."whatsapp_webhook_inbox"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if nullif(btrim(p_worker_id), '') is null then
    raise exception 'worker id is required';
  end if;

  update public.whatsapp_webhook_inbox as exhausted
  set status = 'dead',
      dead_lettered_at = coalesce(exhausted.dead_lettered_at, now()),
      locked_at = null,
      locked_by = null,
      last_error = coalesce(exhausted.last_error, 'retry_exhausted')
  where exhausted.attempts >= exhausted.max_attempts
    and (
      (exhausted.status in ('pending', 'retry') and exhausted.next_attempt_at <= now())
      or (exhausted.status = 'processing' and exhausted.locked_at < now() - p_lease)
    );

  return query
  with candidates as (
    select inbox.id
    from public.whatsapp_webhook_inbox as inbox
    where inbox.attempts < inbox.max_attempts
      and (
        (inbox.status in ('pending', 'retry') and inbox.next_attempt_at <= now())
        or (inbox.status = 'processing' and inbox.locked_at < now() - p_lease)
      )
    order by inbox.next_attempt_at, inbox.created_at, inbox.id
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 50), 500))
  )
  update public.whatsapp_webhook_inbox as claimed
  set status = 'processing',
      attempts = claimed.attempts + 1,
      locked_at = now(),
      locked_by = btrim(p_worker_id),
      last_error = null
  from candidates
  where claimed.id = candidates.id
  returning claimed.*;
end;
$$;


ALTER FUNCTION "private"."claim_whatsapp_webhook_inbox"("p_worker_id" "text", "p_limit" integer, "p_lease" interval) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."complete_whatsapp_webhook_event"("p_event_id" "uuid", "p_worker_id" "text") RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog'
    AS $$
  with completed as (
    update public.whatsapp_webhook_inbox
    set status = 'processed',
        processed_at = now(),
        locked_at = null,
        locked_by = null,
        last_error = null
    where id = p_event_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from completed);
$$;


ALTER FUNCTION "private"."complete_whatsapp_webhook_event"("p_event_id" "uuid", "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."current_audit_actor_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    private.safe_uuid(nullif(current_setting('app.current_user_id', true), '')),
    private.safe_uuid(nullif(current_setting('request.jwt.claim.sub', true), '')),
    (select auth.uid())
  );
$$;


