CREATE OR REPLACE FUNCTION "private"."enforce_active_org_member_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  referenced_user_id uuid;
begin
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and (to_jsonb(new) ->> tg_argv[0]) is not distinct from (to_jsonb(old) ->> tg_argv[0]) then
    return new;
  end if;

  referenced_user_id := nullif(to_jsonb(new) ->> tg_argv[0], '')::uuid;
  if referenced_user_id is null then
    return new;
  end if;

  if not exists (
    select 1
    from public.organization_members om
    join public.users u on u.id = om.user_id
    where om.organization_id = new.organization_id
      and om.user_id = referenced_user_id
      and coalesce(om.is_active, false) = true
      and coalesce(u.is_active, false) = true
  ) then
    raise exception using
      errcode = '23514',
      message = format(
        'Usuario de %s nao e membro ativo da organizacao.',
        tg_argv[0]
      );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_active_org_member_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_portal_tenant_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_name = 'portal_integrations' then
    if new.default_pipeline_id is not null and not exists (
      select 1 from public.pipelines p
      where p.id = new.default_pipeline_id and p.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal pipeline must belong to the integration organization';
    end if;
    if new.default_stage_id is not null and not exists (
      select 1 from public.stages s
      where s.id = new.default_stage_id
        and s.organization_id = new.organization_id
        and (new.default_pipeline_id is null or s.pipeline_id = new.default_pipeline_id)
    ) then
      raise exception using errcode = '23514', message = 'portal stage must belong to the integration organization and pipeline';
    end if;
    if new.default_assigned_user_id is not null and not exists (
      select 1 from public.organization_members om
      where om.organization_id = new.organization_id and om.user_id = new.default_assigned_user_id
    ) then
      raise exception using errcode = '23514', message = 'portal assignee must belong to the integration organization';
    end if;
    if new.default_round_robin_id is not null and not exists (
      select 1 from public.round_robins rr
      where rr.id = new.default_round_robin_id and rr.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal round robin must belong to the integration organization';
    end if;
  elsif tg_table_name = 'portal_listing_publications' then
    if not exists (
      select 1 from public.portal_integrations pi
      where pi.id = new.integration_id
        and pi.organization_id = new.organization_id
        and pi.portal = new.portal
    ) or not exists (
      select 1 from public.properties p
      where p.id = new.property_id and p.organization_id = new.organization_id
    ) then
      raise exception using errcode = '23514', message = 'portal publication references must belong to one organization';
    end if;
  elsif tg_table_name in ('portal_import_reports', 'portal_webhook_events') then
    if not exists (
      select 1 from public.portal_integrations pi
      where pi.id = new.integration_id
        and pi.organization_id = new.organization_id
        and pi.portal = new.portal
    ) then
      raise exception using errcode = '23514', message = 'portal event integration must belong to the event organization';
    end if;
    if tg_table_name = 'portal_webhook_events' then
      if new.lead_id is not null and not exists (
        select 1 from public.leads l where l.id = new.lead_id and l.organization_id = new.organization_id
      ) then
        raise exception using errcode = '23514', message = 'portal event lead must belong to the event organization';
      end if;
      if new.property_id is not null and not exists (
        select 1 from public.properties p where p.id = new.property_id and p.organization_id = new.organization_id
      ) then
        raise exception using errcode = '23514', message = 'portal event property must belong to the event organization';
      end if;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."enforce_portal_tenant_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enforce_tenant_reference"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  reference_id uuid;
  reference_organization_id uuid;
begin
  if tg_op = 'UPDATE'
     and new.organization_id is not distinct from old.organization_id
     and (to_jsonb(new) ->> tg_argv[1]) is not distinct from (to_jsonb(old) ->> tg_argv[1]) then
    return new;
  end if;

  reference_id := nullif(to_jsonb(new) ->> tg_argv[1], '')::uuid;
  if reference_id is null then
    return new;
  end if;

  execute format(
    'select organization_id from public.%I where id = $1',
    tg_argv[0]
  )
  into reference_organization_id
  using reference_id;

  if reference_organization_id is not null
     and new.organization_id is distinct from reference_organization_id then
    raise exception using
      errcode = '23514',
      message = format(
        'Referencia %s.%s pertence a outra organizacao.',
        tg_argv[0],
        tg_argv[1]
      );
  end if;

  return new;
end;
$_$;


ALTER FUNCTION "private"."enforce_tenant_reference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enqueue_activity_gamification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  action_key text;
  activity_reference text;
  normalized_outcome text;
begin
  activity_reference := coalesce(
    nullif(new.metadata->>'task_id', ''),
    nullif(new.metadata->>'schedule_event_id', ''),
    nullif(new.metadata->>'reference_id', ''),
    case
      when new.type in ('proposal_sent', 'contract_signed') then new.lead_id::text
      else new.id::text
    end
  );

  action_key := case lower(new.type)
    when 'call_made' then 'call_made'
    when 'contact_made' then 'contact_made'
    when 'visit_scheduled' then 'visit_scheduled'
    when 'visit_confirmed' then 'visit_confirmed'
    when 'meeting_scheduled' then 'meeting_scheduled'
    when 'meeting_held' then 'meeting_held'
    when 'proposal_sent' then 'proposal_sent'
    when 'contract_signed' then 'contract_signed'
    else null
  end;

  if lower(new.type) = 'task_completed'
    and lower(coalesce(new.metadata->>'task_type', '')) = 'call'
  then
    action_key := 'call_made';
  end if;

  if action_key is not null and new.user_id is not null then
    perform private.enqueue_gamification_outbox(
      new.organization_id,
      new.user_id,
      action_key,
      1,
      activity_reference,
      'activities',
      jsonb_build_object('activity_id', new.id::text, 'producer', 'activities')
    );
  end if;

  normalized_outcome := lower(btrim(coalesce(new.metadata->>'outcome', '')));
  if lower(new.type) = 'task_completed'
    and lower(coalesce(new.metadata->>'task_type', '')) = 'call'
    and normalized_outcome in ('efetivo', 'contato efetivo')
    and new.user_id is not null
  then
    perform private.enqueue_gamification_outbox(
      new.organization_id,
      new.user_id,
      'contact_made',
      1,
      activity_reference,
      'activities',
      jsonb_build_object('activity_id', new.id::text, 'producer', 'activities')
    );
  end if;

  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION "private"."enqueue_activity_gamification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enqueue_automation_event"("target_organization_id" "uuid", "target_event_type" "text", "target_aggregate_type" "text", "target_aggregate_id" "uuid", "target_lead_id" "uuid", "target_conversation_id" "uuid", "target_dedupe_key" "text", "target_payload" "jsonb", "target_available_at" timestamp with time zone DEFAULT "now"()) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if target_organization_id is null
     or target_aggregate_id is null
     or nullif(target_dedupe_key, '') is null
     or not exists (
       select 1
       from public.organization_modules om
       where om.organization_id = target_organization_id
         and lower(trim(om.module_name)) = 'automations'
         and coalesce(om.is_enabled, false) = true
     ) then
    return;
  end if;

  insert into public.automation_event_outbox (
    organization_id, event_type, aggregate_type, aggregate_id,
    lead_id, conversation_id, dedupe_key, payload, available_at
  ) values (
    target_organization_id, target_event_type, target_aggregate_type, target_aggregate_id,
    target_lead_id, target_conversation_id, target_dedupe_key,
    coalesce(target_payload, '{}'::jsonb), coalesce(target_available_at, now())
  ) on conflict (dedupe_key) do nothing;
end;
$$;


ALTER FUNCTION "private"."enqueue_automation_event"("target_organization_id" "uuid", "target_event_type" "text", "target_aggregate_type" "text", "target_aggregate_id" "uuid", "target_lead_id" "uuid", "target_conversation_id" "uuid", "target_dedupe_key" "text", "target_payload" "jsonb", "target_available_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enqueue_gamification_outbox"("target_organization_id" "uuid", "target_user_id" "uuid", "target_action_type" "text", "target_quantity" integer, "target_reference_id" "text", "target_source" "text", "target_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  normalized_action text;
  normalized_reference text;
  active_season_id uuid;
  event_key text;
  outbox_id uuid;
begin
  normalized_action := lower(btrim(coalesce(target_action_type, '')));
  normalized_reference := nullif(btrim(coalesce(target_reference_id, '')), '');

  if target_organization_id is null
    or target_user_id is null
    or normalized_reference is null
    or coalesce(target_quantity, 0) not between 1 and 100
    or normalized_action not in (
      'call_made',
      'message_sent',
      'contact_made',
      'visit_scheduled',
      'visit_confirmed',
      'meeting_scheduled',
      'meeting_held',
      'proposal_sent',
      'sale_closed',
      'contract_signed',
      'lost_lead_recovered',
      'lead_created',
      'lead_created_manual',
      'property_created',
      'prospecting_report'
    )
  then
    return null;
  end if;

  if not exists (
    select 1
    from public.organization_modules as module_access
    where module_access.organization_id = target_organization_id
      and module_access.module_name = 'gamification'
      and module_access.is_enabled = true
  ) or not exists (
    select 1
    from public.organization_members as membership
    where membership.organization_id = target_organization_id
      and membership.user_id = target_user_id
      and membership.is_active = true
  ) or exists (
    select 1
    from public.gamification_participants as participant
    where participant.organization_id = target_organization_id
      and participant.user_id = target_user_id
      and participant.participates = false
  )
  then
    return null;
  end if;

  -- SHARE locks are compatible across hot-path enqueues. A season reset takes
  -- UPDATE on this one module row, giving the reset a deterministic boundary
  -- without serializing messages/leads against each other.
  perform 1
  from public.organization_modules as module_access
  where module_access.organization_id = target_organization_id
    and module_access.module_name = 'gamification'
  for share;

  select season.id
  into active_season_id
  from public.gamification_seasons as season
  where season.organization_id = target_organization_id
    and season.is_active = true
  order by season.started_at desc, season.id desc
  limit 1
  for key share;

  if active_season_id is null then
    return null;
  end if;

  event_key := concat_ws(
    '|',
    'v1',
    target_organization_id::text,
    normalized_action,
    normalized_reference
  );

  insert into public.gamification_outbox (
    organization_id,
    season_id,
    user_id,
    action_type,
    quantity,
    source,
    reference_id,
    idempotency_key,
    metadata
  )
  values (
    target_organization_id,
    active_season_id,
    target_user_id,
    normalized_action,
    target_quantity,
    coalesce(nullif(btrim(target_source), ''), 'database_trigger'),
    normalized_reference,
    event_key,
    coalesce(target_metadata, '{}'::jsonb)
  )
  on conflict (organization_id, idempotency_key) do nothing
  returning id into outbox_id;

  if outbox_id is null then
    select existing.id
    into outbox_id
    from public.gamification_outbox as existing
    where existing.organization_id = target_organization_id
      and existing.idempotency_key = event_key;
  end if;

  return outbox_id;
end;
$$;


ALTER FUNCTION "private"."enqueue_gamification_outbox"("target_organization_id" "uuid", "target_user_id" "uuid", "target_action_type" "text", "target_quantity" integer, "target_reference_id" "text", "target_source" "text", "target_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."enqueue_lead_gamification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  beneficiary_id uuid;
  action_key text;
begin
  if tg_op = 'INSERT' then
    if lower(coalesce(new.source, 'manual')) = 'manual' then
      action_key := 'lead_created_manual';
      beneficiary_id := coalesce(new.created_by, new.assigned_user_id);
    else
      action_key := 'lead_created';
      beneficiary_id := coalesce(new.assigned_user_id, new.created_by);
    end if;

    perform private.enqueue_gamification_outbox(
      new.organization_id,
      beneficiary_id,
      action_key,
      1,
      new.id::text,
      'leads',
      jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_insert')
    );
  elsif tg_op = 'UPDATE' and old.deal_status is distinct from new.deal_status then
    beneficiary_id := new.assigned_user_id;
    if new.deal_status = 'won' then
      perform private.enqueue_gamification_outbox(
        new.organization_id,
        beneficiary_id,
        'sale_closed',
        1,
        new.id::text,
        'leads',
        jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_deal_status')
      );
    elsif old.deal_status = 'lost' and new.deal_status = 'open' then
      perform private.enqueue_gamification_outbox(
        new.organization_id,
        beneficiary_id,
        'lost_lead_recovered',
        1,
        new.id::text,
        'leads',
        jsonb_build_object('lead_id', new.id::text, 'producer', 'leads_deal_status')
      );
    end if;
  end if;

  return new;
exception
  when others then
    raise warning 'gamification producer % skipped: [%] %', tg_name, sqlstate, sqlerrm;
    return new;
end;
$$;


ALTER FUNCTION "private"."enqueue_lead_gamification"() OWNER TO "postgres";


