CREATE OR REPLACE FUNCTION "private"."ensure_whatsapp_outbox_provider_request_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  action_name text := btrim(coalesce(new.payload->>'action', ''));
  request_id text;
begin
  if action_name not in ('send.text', 'send.media', 'send.audio') then
    return new;
  end if;

  if jsonb_typeof(new.payload->'body') is distinct from 'object' then
    raise exception using
      errcode = '23514',
      message = 'invalid_whatsapp_outbox_send_body';
  end if;

  request_id := upper(substr(
    encode(extensions.digest(btrim(new.client_message_id), 'sha256'), 'hex'),
    1,
    32
  ));

  if nullif(btrim(coalesce(new.payload->'body'->>'id', '')), '') is null then
    new.payload := jsonb_set(
      coalesce(new.payload, '{}'::jsonb),
      '{body,id}',
      to_jsonb(request_id),
      true
    );
  elsif new.payload->'body'->>'id' is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_request_id_mismatch';
  end if;

  if new.payload->'body'->>'id' is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_request_id_missing_after_guard';
  end if;

  if new.provider_message_id is null then
    new.provider_message_id := request_id;
  elsif new.provider_message_id is distinct from request_id then
    raise exception using
      errcode = '23514',
      message = 'whatsapp_outbox_provider_message_id_mismatch';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."ensure_whatsapp_outbox_provider_request_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."fail_whatsapp_outbox"("p_outbox_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retry_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_permanent" boolean DEFAULT false) RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog'
    AS $$
  with failed as (
    update public.whatsapp_outbox
    set status = case
          when p_permanent then 'failed'
          when attempts >= max_attempts then 'dead'
          else 'retry'
        end,
        next_attempt_at = case
          when p_permanent or attempts >= max_attempts then next_attempt_at
          else coalesce(p_retry_at, now() + make_interval(secs => least(3600, 5 * power(2, least(attempts, 9))::integer)))
        end,
        failed_at = case when p_permanent then now() else failed_at end,
        dead_lettered_at = case when not p_permanent and attempts >= max_attempts then now() else null end,
        locked_at = null,
        locked_by = null,
        last_error = left(coalesce(nullif(p_error, ''), 'unknown_error'), 4000)
    where id = p_outbox_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from failed);
$$;


ALTER FUNCTION "private"."fail_whatsapp_outbox"("p_outbox_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retry_at" timestamp with time zone, "p_permanent" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."fail_whatsapp_webhook_event"("p_event_id" "uuid", "p_worker_id" "text", "p_error" "text", "p_retry_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog'
    AS $$
  with failed as (
    update public.whatsapp_webhook_inbox
    set status = case when attempts >= max_attempts then 'dead' else 'retry' end,
        next_attempt_at = case
          when attempts >= max_attempts then next_attempt_at
          else coalesce(p_retry_at, now() + make_interval(secs => least(3600, 5 * power(2, least(attempts, 9))::integer)))
        end,
        dead_lettered_at = case when attempts >= max_attempts then now() else null end,
        locked_at = null,
        locked_by = null,
        last_error = left(coalesce(nullif(p_error, ''), 'unknown_error'), 4000)
    where id = p_event_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from failed);
$$;


