CREATE OR REPLACE FUNCTION "private"."guard_lead_clocks"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.attention_eligible := true;
    new.attention_enrolled_at := coalesce(new.attention_enrolled_at, now());
    if new.stage_id is not null then
      new.stage_entered_at := coalesce(new.stage_entered_at, new.created_at, now());
    end if;
    if new.assigned_user_id is not null then
      new.assigned_at := coalesce(new.assigned_at, new.created_at, now());
    end if;
    new.board_order_at := coalesce(new.board_order_at, new.last_entry_at, new.stage_entered_at, new.created_at, now());
    return new;
  end if;

  new.attention_eligible := old.attention_eligible;
  new.attention_enrolled_at := old.attention_enrolled_at;
  if new.stage_id is not distinct from old.stage_id and new.pipeline_id is not distinct from old.pipeline_id then
    new.stage_entered_at := old.stage_entered_at;
  elsif new.stage_id is null then
    new.stage_entered_at := null;
    new.board_order_at := null;
  else
    new.stage_entered_at := now();
    if new.board_order_at is not distinct from old.board_order_at then new.board_order_at := new.stage_entered_at; end if;
  end if;
  if new.assigned_user_id is distinct from old.assigned_user_id then
    new.assigned_at := case when new.assigned_user_id is null then null else now() end;
  end if;
  new.board_order_at := coalesce(new.board_order_at, old.board_order_at, new.stage_entered_at, new.created_at, now());
  return new;
end;
$$;


ALTER FUNCTION "private"."guard_lead_clocks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."has_org_role"("target_organization_id" "uuid", "allowed_roles" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and exists (
        select 1
        from public.organization_members om
        where om.user_id = (select auth.uid())
          and om.organization_id = target_organization_id
          and coalesce(om.is_active, false) = true
          and om.role = any(allowed_roles)
      )
    );
$$;


ALTER FUNCTION "private"."has_org_role"("target_organization_id" "uuid", "allowed_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."has_permission"("target_organization_id" "uuid", "permission_key" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
  select private.is_super_admin()
    or (
      private.is_org_member(target_organization_id)
      and (
        exists (
          select 1
          from public.organization_members om
          where om.user_id = (select auth.uid())
            and om.organization_id = target_organization_id
            and coalesce(om.is_active, false) = true
            and om.role in ('owner', 'admin')
        )
        or exists (
          select 1
          from public.user_organization_roles uor
          join public.organization_roles role
            on role.id = uor.role_id
           and role.organization_id = uor.organization_id
          join public.organization_role_permissions orp
            on orp.role_id = uor.role_id
           and orp.organization_id = uor.organization_id
          join public.available_permissions permission
            on permission.id = orp.permission_id
          where uor.user_id = (select auth.uid())
            and uor.organization_id = target_organization_id
            and coalesce(uor.is_active, false) = true
            and coalesce(role.is_active, false) = true
            and permission.key = $2
        )
      )
    );
$_$;


ALTER FUNCTION "private"."has_permission"("target_organization_id" "uuid", "permission_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."imoview_delete_api_key"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
begin
  if old.api_key_secret_ref is not null then
    delete from vault.secrets where id = old.api_key_secret_ref;
  end if;
  return old;
end;
$$;


ALTER FUNCTION "private"."imoview_delete_api_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."imoview_store_api_key"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'vault', 'private'
    AS $$
declare
  secret_value text := nullif(btrim(new.api_key), '');
  secret_id uuid := new.api_key_secret_ref;
  secret_name text := 'vimob_imoview_api_key_' || new.organization_id::text;
begin
  perform pg_advisory_xact_lock(hashtextextended('imoview_api_key:' || new.organization_id::text, 0));

  if secret_id is null then
    select i.api_key_secret_ref into secret_id
    from public.imoview_integrations i
    where i.organization_id = new.organization_id
    limit 1;
  end if;

  if secret_id is null then
    select s.id into secret_id
    from vault.secrets s
    where s.name = secret_name;
  end if;

  if secret_value is not null then
    if secret_id is null then
      secret_id := vault.create_secret(
        secret_value,
        secret_name,
        'Imoview API key for organization ' || new.organization_id::text
      );
    else
      perform vault.update_secret(
        secret_id,
        secret_value,
        secret_name,
        'Imoview API key for organization ' || new.organization_id::text
      );
    end if;
  end if;

  if secret_id is null then
    raise exception 'Imoview API key is required';
  end if;

  new.api_key_secret_ref := secret_id;
  new.api_key := null;
  return new;
end;
$$;


ALTER FUNCTION "private"."imoview_store_api_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
      AND u.role = 'admin'
  );
$$;


