CREATE OR REPLACE FUNCTION "private"."is_org_member"("target_organization_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select private.is_super_admin()
    or (
      target_organization_id is not null
      and exists (
        select 1
        from public.organization_members om
        join public.users u on u.id = om.user_id
        join public.organizations o on o.id = om.organization_id
        where om.user_id = (select auth.uid())
          and om.organization_id = target_organization_id
          and coalesce(om.is_active, false) = true
          and coalesce(u.is_active, false) = true
          and coalesce(o.is_active, true) = true
      )
    );
$$;


ALTER FUNCTION "private"."is_org_member"("target_organization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."is_pipeline_in_led_team"("p_pipeline_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.team_members tm
    join public.teams t on t.id = tm.team_id
    join public.team_pipelines tp on tp.team_id = tm.team_id
    where tm.user_id = p_user_id
      and coalesce(tm.is_leader, false) = true
      and coalesce(t.is_active, true) = true
      and t.organization_id = public.get_user_organization_id()
      and tp.pipeline_id = p_pipeline_id
  );
$$;


