CREATE OR REPLACE FUNCTION "private"."mark_whatsapp_outbox_sent"("p_outbox_id" "uuid", "p_worker_id" "text", "p_provider_message_id" "text", "p_sent_at" timestamp with time zone DEFAULT "now"()) RETURNS boolean
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog'
    AS $$
  with sent as (
    update public.whatsapp_outbox
    set status = 'sent',
        provider_message_id = nullif(btrim(p_provider_message_id), ''),
        sent_at = coalesce(p_sent_at, now()),
        locked_at = null,
        locked_by = null,
        last_error = null
    where id = p_outbox_id
      and status = 'processing'
      and locked_by = btrim(p_worker_id)
    returning id
  )
  select exists(select 1 from sent);
$$;


