CREATE OR REPLACE FUNCTION "private"."materialize_cadence_for_stage_cycle"("p_stage_cycle_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_cycle record;
  target_template record;
  enrollment_id uuid;
begin
  select sc.*, l.assigned_user_id, s.stage_key, s.name as stage_name
  into target_cycle
  from public.lead_stage_cycles sc
  join public.leads l on l.id = sc.lead_id and l.organization_id = sc.organization_id
  join public.stages s on s.id = sc.stage_id and s.organization_id = sc.organization_id
  where sc.id = p_stage_cycle_id and sc.exited_at is null;
  if not found then return null; end if;

  select ct.*
  into target_template
  from public.cadence_templates ct
  where ct.organization_id = target_cycle.organization_id
    and coalesce(ct.is_active, true) = true
    and (
      ct.stage_id = target_cycle.stage_id
      or (ct.pipeline_id = target_cycle.pipeline_id and ct.stage_key = target_cycle.stage_key)
      or (ct.pipeline_id is null and ct.stage_key = target_cycle.stage_key)
    )
  order by
    case when ct.stage_id = target_cycle.stage_id then 3
         when ct.pipeline_id = target_cycle.pipeline_id then 2 else 1 end desc,
    ct.updated_at desc,
    ct.id
  limit 1;
  if not found then return null; end if;

  update public.cadence_enrollments
  set status = 'cancelled', cancelled_at = now(), cancel_reason = 'cadence_replaced', updated_at = now()
  where lead_id = target_cycle.lead_id and status = 'active';

  insert into public.cadence_enrollments (
    organization_id, lead_id, cadence_template_id, stage_cycle_id,
    assigned_user_id, started_at, template_snapshot, metadata
  ) values (
    target_cycle.organization_id, target_cycle.lead_id, target_template.id, target_cycle.id,
    target_cycle.assigned_user_id, target_cycle.entered_at,
    jsonb_build_object(
      'id', target_template.id,
      'name', target_template.name,
      'pipeline_id', target_template.pipeline_id,
      'stage_id', target_template.stage_id,
      'stage_key', target_template.stage_key
    ),
    jsonb_build_object('source', 'stage_cycle', 'stage_name', target_cycle.stage_name)
  )
  on conflict (stage_cycle_id) where stage_cycle_id is not null and status = 'active' do update
    set assigned_user_id = excluded.assigned_user_id,
        updated_at = now()
  returning id into enrollment_id;

  insert into public.lead_tasks (
    organization_id, lead_id, assigned_user_id, title, description, type,
    day_offset, due_at, due_date, is_done, status, sequence,
    cadence_enrollment_id, cadence_template_task_id, metadata
  )
  select
    target_cycle.organization_id,
    target_cycle.lead_id,
    target_cycle.assigned_user_id,
    task.title,
    nullif(task.metadata->>'description', ''),
    coalesce(nullif(task.type, ''), 'call'),
    greatest(0, task.delay_days),
    target_cycle.entered_at + make_interval(days => greatest(0, task.delay_days)),
    target_cycle.entered_at + make_interval(days => greatest(0, task.delay_days)),
    false,
    'pending',
    task.position,
    enrollment_id,
    task.id,
    coalesce(task.metadata, '{}'::jsonb) || jsonb_build_object(
      'source', 'cadence',
      'cadence_template_id', target_template.id,
      'message_template', task.message_template
    )
  from public.cadence_tasks_template task
  where task.organization_id = target_cycle.organization_id
    and task.cadence_template_id = target_template.id
  on conflict (cadence_enrollment_id, cadence_template_task_id)
    where cadence_enrollment_id is not null and cadence_template_task_id is not null
  do nothing;

  if not exists (
    select 1 from public.lead_tasks where cadence_enrollment_id = enrollment_id and status = 'pending'
  ) then
    update public.cadence_enrollments
    set status = 'completed', completed_at = now(), updated_at = now()
    where id = enrollment_id;
  end if;

  return enrollment_id;
end;
$$;


ALTER FUNCTION "private"."materialize_cadence_for_stage_cycle"("p_stage_cycle_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."notify_automation_attention"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_user_id" "uuid", "p_title" "text", "p_content" "text", "p_event_key" "text", "p_dedupe_key" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_user_id is null or nullif(trim(coalesce(p_dedupe_key, '')), '') is null then
    return;
  end if;

  insert into public.notifications (
    organization_id, user_id, title, content, body, type, channel,
    lead_id, target_url, is_read, metadata
  ) values (
    p_organization_id,
    p_user_id,
    left(coalesce(nullif(trim(p_title), ''), 'Automacao requer atencao'), 200),
    left(coalesce(p_content, ''), 2000),
    left(coalesce(p_content, ''), 2000),
    'lead',
    'in_app',
    p_lead_id,
    '/crm/conversas?lead=' || p_lead_id::text,
    false,
    jsonb_build_object(
      'event_key', p_event_key,
      'dedupe_key', p_dedupe_key,
      'whatsapp_dispatch_required', false,
      'dispatch', jsonb_build_object(
        'whatsapp', jsonb_build_object('required', false, 'status', 'skipped'),
        'push', jsonb_build_object('required', true, 'status', 'pending')
      )
    ) || coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict do nothing;
end;
$$;


ALTER FUNCTION "private"."notify_automation_attention"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_user_id" "uuid", "p_title" "text", "p_content" "text", "p_event_key" "text", "p_dedupe_key" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."record_lead_action_fact"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_actor_user_id" "uuid", "p_action_type" "text", "p_channel" "text", "p_occurred_at" timestamp with time zone, "p_is_automated" boolean, "p_is_inbound" boolean, "p_qualifies_first_outreach" boolean, "p_qualifies_stage_inactivity" boolean, "p_is_effective_contact" boolean, "p_source_type" "text", "p_source_id" "text", "p_metadata" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
declare
  current_assignment_cycle_id uuid;
  current_stage_cycle_id uuid;
begin
  if not exists (
    select 1
    from public.leads
    where id = p_lead_id
      and organization_id = p_organization_id
      and attention_eligible = true
  ) then
    return;
  end if;

  select id into current_assignment_cycle_id
  from public.lead_assignment_cycles
  where lead_id = p_lead_id and ended_at is null
  order by assigned_at desc, id desc
  limit 1;

  select id into current_stage_cycle_id
  from public.lead_stage_cycles
  where lead_id = p_lead_id and exited_at is null
  order by entered_at desc, id desc
  limit 1;

  insert into public.lead_action_facts (
    organization_id, lead_id, actor_user_id, assignment_cycle_id, stage_cycle_id,
    action_type, channel, occurred_at, is_automated, is_inbound,
    qualifies_first_outreach, qualifies_stage_inactivity, is_effective_contact,
    source_type, source_id, metadata
  ) values (
    p_organization_id, p_lead_id, p_actor_user_id, current_assignment_cycle_id, current_stage_cycle_id,
    btrim(p_action_type), nullif(btrim(coalesce(p_channel, '')), ''), coalesce(p_occurred_at, now()),
    coalesce(p_is_automated, false), coalesce(p_is_inbound, false),
    coalesce(p_qualifies_first_outreach, false), coalesce(p_qualifies_stage_inactivity, false),
    coalesce(p_is_effective_contact, false), btrim(p_source_type), nullif(btrim(coalesce(p_source_id, '')), ''),
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (organization_id, source_type, source_id)
    where source_id is not null
  do nothing;
end;
$$;


ALTER FUNCTION "private"."record_lead_action_fact"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_actor_user_id" "uuid", "p_action_type" "text", "p_channel" "text", "p_occurred_at" timestamp with time zone, "p_is_automated" boolean, "p_is_inbound" boolean, "p_qualifies_first_outreach" boolean, "p_qualifies_stage_inactivity" boolean, "p_is_effective_contact" boolean, "p_source_type" "text", "p_source_id" "text", "p_metadata" "jsonb") OWNER TO "postgres";


