CREATE OR REPLACE FUNCTION "private"."user_has_permission"("p_permission_key" "text", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_user_role TEXT;
  v_has_permission BOOLEAN;
BEGIN
  -- Super admin tem todas as permissões
  IF public.is_super_admin() THEN
    RETURN TRUE;
  END IF;

  -- Verificar se é admin da organização (admin tem todas as permissões)
  SELECT role INTO v_user_role FROM public.users WHERE id = p_user_id;
  IF v_user_role = 'admin' THEN
    RETURN TRUE;
  END IF;

  -- Verificar permissão pela função customizada
  SELECT EXISTS (
    SELECT 1
    FROM public.user_organization_roles uor
    JOIN public.organization_role_permissions orp ON orp.organization_role_id = uor.organization_role_id
    WHERE uor.user_id = p_user_id
      AND orp.permission_key = p_permission_key
  ) INTO v_has_permission;

  RETURN COALESCE(v_has_permission, FALSE);
END;
$$;


ALTER FUNCTION "private"."user_has_permission"("p_permission_key" "text", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."validate_whatsapp_worker_tenant_shape"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shape_is_valid boolean := false;
begin
  if tg_table_name = 'whatsapp_webhook_inbox' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      where session.id = new.session_id
        and session.organization_id = new.organization_id
    ) into shape_is_valid;
  elsif tg_table_name = 'whatsapp_outbox' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      join public.whatsapp_conversations as conversation
        on conversation.id = new.conversation_id
       and conversation.organization_id = new.organization_id
       and conversation.session_id = new.session_id
      join public.whatsapp_messages as message
        on message.id = new.message_id
       and message.organization_id = new.organization_id
       and message.conversation_id = new.conversation_id
       and message.session_id = new.session_id
      where session.id = new.session_id
        and session.organization_id = new.organization_id
    ) into shape_is_valid;
  elsif tg_table_name = 'whatsapp_message_reactions' then
    select exists (
      select 1
      from public.whatsapp_sessions as session
      join public.whatsapp_conversations as conversation
        on conversation.id = new.conversation_id
       and conversation.organization_id = new.organization_id
       and conversation.session_id = new.session_id
      where session.id = new.session_id
        and session.organization_id = new.organization_id
        and (
          new.target_message_id is null
          or exists (
            select 1
            from public.whatsapp_messages as message
            where message.id = new.target_message_id
              and message.organization_id = new.organization_id
              and message.conversation_id = new.conversation_id
              and message.session_id = new.session_id
          )
        )
    ) into shape_is_valid;
  end if;

  if not shape_is_valid then
    raise exception using
      errcode = '23514',
      message = 'WhatsApp worker row crosses organization, session, conversation, or message boundaries';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "private"."validate_whatsapp_worker_tenant_shape"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."vimob_can_access_whatsapp_session"("p_session_id" "uuid", "p_permission" "text" DEFAULT 'view'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.whatsapp_sessions ws
    where ws.id = p_session_id
      and coalesce(ws.is_active, true) = true
      and coalesce(ws.status, '') <> 'deleted'
      and ws.provider = 'evolution_go'
      and ws.owner_user_id = (select auth.uid())
      and (
        exists (
          select 1
          from public.users u
          where u.id = (select auth.uid())
            and u.organization_id = ws.organization_id
            and coalesce(u.is_active, true) = true
        )
        or exists (
          select 1
          from public.organization_members om
          where om.organization_id = ws.organization_id
            and om.user_id = (select auth.uid())
            and om.is_active = true
        )
      )
  );
$$;


