CREATE OR REPLACE FUNCTION "public"."cancel_disabled_automation_runtime"("p_batch_size" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  execution_count integer := 0;
  event_count integer := 0;
  closed_step_count integer := 0;
begin
  with candidates as (
    select e.id
    from public.automation_executions e
    where e.status in ('queued', 'running', 'waiting')
      and not exists (
        select 1 from public.organization_modules om
        where om.organization_id = e.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by e.started_at, e.id
    limit least(greatest(coalesce(p_batch_size, 100), 1), 500)
    for update skip locked
  )
  , cancelled as (
    update public.automation_executions e
    set status = 'cancelled',
        cancellation_requested_at = now(),
        completed_at = now(),
        error_message = 'module_disabled',
        locked_at = null,
        locked_by = null,
        updated_at = now()
    from candidates c
    where e.id = c.id
    returning e.id
  ), closed_steps as (
    update public.automation_execution_steps s
    set status = 'cancelled', completed_at = now(), error_message = 'module_disabled'
    where s.execution_id in (select id from cancelled)
      and s.status in ('running', 'waiting')
    returning s.id
  )
  select
    (select count(*) from cancelled),
    (select count(*) from closed_steps)
  into execution_count, closed_step_count;

  with candidates as (
    select o.id
    from public.automation_event_outbox o
    where o.status in ('pending', 'failed', 'processing')
      and not exists (
        select 1 from public.organization_modules om
        where om.organization_id = o.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by o.created_at, o.id
    limit least(greatest(coalesce(p_batch_size, 100), 1), 500)
    for update skip locked
  )
  update public.automation_event_outbox o
  set status = 'dead_letter',
      dead_lettered_at = now(),
      last_error = 'module_disabled',
      locked_at = null,
      locked_by = null,
      updated_at = now()
  from candidates c
  where o.id = c.id;
  get diagnostics event_count = row_count;

  return jsonb_build_object(
    'executions_cancelled', execution_count,
    'steps_cancelled', closed_step_count,
    'events_dead_lettered', event_count
  );
end;
$$;


ALTER FUNCTION "public"."cancel_disabled_automation_runtime"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_edge_rate_limit"("p_scope" "text", "p_identifier_hash" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS TABLE("allowed" boolean, "remaining" integer, "retry_after_seconds" integer)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_window_start timestamptz;
  v_count integer;
  v_retry_after integer;
begin
  if p_scope is null or length(trim(p_scope)) = 0 then
    raise exception 'p_scope is required';
  end if;

  if p_identifier_hash is null or length(trim(p_identifier_hash)) = 0 then
    raise exception 'p_identifier_hash is required';
  end if;

  if p_limit <= 0 or p_window_seconds <= 0 then
    raise exception 'p_limit and p_window_seconds must be positive';
  end if;

  v_window_start := to_timestamp(
    floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds
  );

  insert into public.edge_rate_limits (
    scope,
    identifier_hash,
    window_start,
    window_seconds,
    request_count
  )
  values (
    p_scope,
    p_identifier_hash,
    v_window_start,
    p_window_seconds,
    1
  )
  on conflict (scope, identifier_hash, window_start)
  do update set
    request_count = public.edge_rate_limits.request_count + 1,
    updated_at = now()
  returning request_count into v_count;

  v_retry_after := greatest(
    1,
    ceil(extract(epoch from (v_window_start + (p_window_seconds * interval '1 second') - now())))::integer
  );

  return query
  select
    v_count <= p_limit,
    greatest(p_limit - v_count, 0),
    case when v_count > p_limit then v_retry_after else 0 end;
end;
$$;


ALTER FUNCTION "public"."check_edge_rate_limit"("p_scope" "text", "p_identifier_hash" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_ranking_overtake"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_overtaken_user_id UUID;
    v_overtaker_name TEXT;
    v_overtaken_name TEXT;
BEGIN
    IF NEW.total_points > OLD.total_points THEN
        -- Busca quem estava na frente e agora ficou atrás
        SELECT user_id INTO v_overtaken_user_id
        FROM public.user_gamification_stats
        WHERE organization_id = NEW.organization_id
          AND total_points >= OLD.total_points
          AND total_points < NEW.total_points
          AND user_id != NEW.user_id
        ORDER BY total_points DESC LIMIT 1;

        IF v_overtaken_user_id IS NOT NULL THEN
            SELECT name INTO v_overtaker_name FROM public.users WHERE id = NEW.user_id;
            SELECT name INTO v_overtaken_name FROM public.users WHERE id = v_overtaken_user_id;

            -- Notifica quem caiu
            INSERT INTO public.notifications (user_id, organization_id, title, content, type)
            VALUES (v_overtaken_user_id, NEW.organization_id, '⚠️ Você foi ultrapassado!', v_overtaker_name || ' te passou no ranking!', 'gamification_overtake');

            -- Notifica quem subiu
            INSERT INTO public.notifications (user_id, organization_id, title, content, type)
            VALUES (NEW.user_id, NEW.organization_id, '🚀 Subiu no Ranking!', 'Você ultrapassou ' || v_overtaken_name || '!', 'gamification_overtake');
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_ranking_overtake"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_storage_org_access"("org_id_text" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org_id uuid;
BEGIN
  -- Try to parse the text as UUID. If it fails, deny access.
  BEGIN
    org_id := org_id_text::uuid;
  EXCEPTION WHEN others THEN
    RETURN FALSE;
  END;

  RETURN EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = auth.uid()
    AND (
      u.organization_id = org_id
      OR u.role = 'super_admin'
      OR EXISTS (
        SELECT 1 FROM public.organization_members om
        WHERE om.user_id = u.id AND om.organization_id = org_id
      )
    )
  );
END;
$$;


ALTER FUNCTION "public"."check_storage_org_access"("org_id_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_whatsapp_conversation_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Se o organization_id não foi enviado, ou para garantir integridade,
  -- buscamos da sessão que o usuário já tem acesso.
  SELECT organization_id INTO NEW.organization_id
  FROM public.whatsapp_sessions
  WHERE id = NEW.session_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."check_whatsapp_conversation_insert"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."automation_event_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "event_type" "text" NOT NULL,
    "aggregate_type" "text" NOT NULL,
    "aggregate_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "conversation_id" "uuid",
    "dedupe_key" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 8 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_at" timestamp with time zone,
    "locked_by" "text",
    "completed_at" timestamp with time zone,
    "dead_lettered_at" timestamp with time zone,
    "last_error" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_event_outbox_attempts_check" CHECK ((("attempts" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 25)))),
    CONSTRAINT "automation_event_outbox_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'failed'::"text", 'dead_letter'::"text"]))),
    CONSTRAINT "automation_event_outbox_type_check" CHECK (("event_type" = ANY (ARRAY['message_received'::"text", 'scheduled'::"text", 'lead_stage_changed'::"text", 'lead_created'::"text", 'tag_added'::"text", 'inactivity'::"text", 'manual'::"text"])))
);


ALTER TABLE "public"."automation_event_outbox" OWNER TO "postgres";


COMMENT ON TABLE "public"."automation_event_outbox" IS 'Backend-only table: RLS without policies and no client grants intentionally enforce default deny.';



CREATE OR REPLACE FUNCTION "public"."claim_automation_events"("p_worker_id" "text", "p_batch_size" integer DEFAULT 25) RETURNS SETOF "public"."automation_event_outbox"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with exhausted_candidates as (
    select o.id
    from public.automation_event_outbox o
    where o.status = 'processing'
      and o.attempts >= o.max_attempts
      and o.locked_at < now() - interval '5 minutes'
    order by o.locked_at, o.id
    limit 100
    for update skip locked
  ), exhausted as (
    update public.automation_event_outbox o
    set status = 'dead_letter', dead_lettered_at = now(),
        locked_at = null, locked_by = null,
        last_error = coalesce(o.last_error, 'retry_exhausted'), updated_at = now()
    from exhausted_candidates c
    where o.id = c.id
    returning o.id
  ), candidates as (
    select o.id
    from public.automation_event_outbox o
    where o.attempts < o.max_attempts
      and o.available_at <= now()
      and exists (
        select 1 from public.organization_modules om
        where om.organization_id = o.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
      and (
        o.status in ('pending', 'failed')
        or (o.status = 'processing' and o.locked_at < now() - interval '5 minutes')
      )
    order by o.available_at, o.created_at, o.id
    limit least(greatest(coalesce(p_batch_size, 25), 1), 100)
    for update skip locked
  ), claimed as (
    update public.automation_event_outbox o
    set status = 'processing',
        attempts = o.attempts + 1,
        locked_at = now(),
        locked_by = left(coalesce(p_worker_id, 'worker'), 200),
        updated_at = now()
    from candidates c
    where o.id = c.id
    returning o.*
  )
  select * from claimed;
$$;


ALTER FUNCTION "public"."claim_automation_events"("p_worker_id" "text", "p_batch_size" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."automation_executions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "automation_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "conversation_id" "uuid",
    "organization_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "current_node_id" "uuid",
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completed_at" timestamp with time zone,
    "error_message" "text",
    "execution_data" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "next_execution_at" timestamp with time zone,
    "lock_token" "text",
    "locked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "flow_version_id" "uuid",
    "trigger_event_id" "uuid",
    "current_node_key" "text",
    "cancellation_requested_at" timestamp with time zone,
    "locked_by" "text",
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "automation_executions_status_check" CHECK (("status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'waiting'::"text", 'completed'::"text", 'failed'::"text", 'cancelled'::"text", 'canceled'::"text"])))
);


ALTER TABLE "public"."automation_executions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_automation_executions"("p_worker_id" "text", "p_batch_size" integer DEFAULT 25) RETURNS SETOF "public"."automation_executions"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with exhausted_candidates as (
    select e.id
    from public.automation_executions e
    where e.flow_version_id is not null
      and e.status in ('queued', 'running')
      and e.attempt_count >= 25
      and (e.status = 'queued' or e.locked_at < now() - interval '15 minutes')
    order by e.started_at, e.id
    limit 100
    for update skip locked
  ), exhausted as (
    update public.automation_executions e
    set status = 'failed', completed_at = now(), error_message = 'retry_exhausted',
        locked_at = null, locked_by = null, updated_at = now()
    from exhausted_candidates c
    where e.id = c.id
    returning e.id
  ), exhausted_steps as (
    update public.automation_execution_steps s
    set status = 'failed', completed_at = now(), error_message = 'retry_exhausted'
    where s.execution_id in (select id from exhausted)
      and s.status in ('running', 'waiting')
    returning s.id
  ), candidates as (
    select e.id
    from public.automation_executions e
    where e.flow_version_id is not null
      and e.cancellation_requested_at is null
      and e.attempt_count < 25
      and exists (
        select 1 from public.organization_modules om
        where om.organization_id = e.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
      and (
        e.status = 'queued'
        or (e.status = 'running' and e.locked_at < now() - interval '15 minutes')
      )
    order by e.started_at, e.id
    limit least(greatest(coalesce(p_batch_size, 25), 1), 100)
    for update skip locked
  ), claimed as (
    update public.automation_executions e
    set status = 'running',
        attempt_count = e.attempt_count + 1,
        locked_at = now(),
        locked_by = left(coalesce(p_worker_id, 'worker'), 200),
        error_message = null,
        updated_at = now()
    from candidates c
    where e.id = c.id
    returning e.*
  ) select * from claimed;
$$;


ALTER FUNCTION "public"."claim_automation_executions"("p_worker_id" "text", "p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_orphan_members"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  team_deleted_count int := 0;
  rr_deleted_count int := 0;
  deleted_count int;
BEGIN
  -- 1. Deletar membros de equipe onde usuário tem org NULL ou org diferente
  WITH deleted AS (
    DELETE FROM team_members tm
    USING teams t
    WHERE tm.team_id = t.id
      AND tm.user_id IN (
        SELECT u.id FROM users u
        WHERE u.organization_id IS NULL
           OR u.organization_id != t.organization_id
      )
    RETURNING tm.id
  )
  SELECT count(*) INTO deleted_count FROM deleted;
  team_deleted_count := team_deleted_count + deleted_count;

  -- 2. Deletar membros de equipe onde usuário não existe mais
  WITH deleted AS (
    DELETE FROM team_members
    WHERE user_id NOT IN (SELECT id FROM users)
    RETURNING id
  )
  SELECT count(*) INTO deleted_count FROM deleted;
  team_deleted_count := team_deleted_count + deleted_count;

  -- 3. Deletar membros de round-robin onde usuário tem org NULL ou org diferente
  WITH deleted AS (
    DELETE FROM round_robin_members rrm
    USING round_robins rr
    WHERE rrm.round_robin_id = rr.id
      AND rrm.user_id IN (
        SELECT u.id FROM users u
        WHERE u.organization_id IS NULL
           OR u.organization_id != rr.organization_id
      )
    RETURNING rrm.id
  )
  SELECT count(*) INTO deleted_count FROM deleted;
  rr_deleted_count := rr_deleted_count + deleted_count;

  -- 4. Deletar membros de round-robin onde usuário não existe mais
  WITH deleted AS (
    DELETE FROM round_robin_members
    WHERE user_id NOT IN (SELECT id FROM users)
    RETURNING id
  )
  SELECT count(*) INTO deleted_count FROM deleted;
  rr_deleted_count := rr_deleted_count + deleted_count;

  RETURN jsonb_build_object(
    'team_members_removed', team_deleted_count,
    'round_robin_members_removed', rr_deleted_count,
    'executed_at', now()
  );
END;
$$;


ALTER FUNCTION "public"."cleanup_orphan_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_whatsapp_retention"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  deleted_msgs integer := 0;
  deleted_convs integer := 0;
  deleted_jobs integer := 0;
  deleted_meta integer := 0;
begin
  with del as (
    delete from public.whatsapp_messages m
    using public.whatsapp_conversations c
    where c.id = m.conversation_id
      and c.is_group = true
      and c.lead_id is null
      and m.sent_at < now() - interval '15 days'
    returning m.id
  )
  select count(*) into deleted_msgs from del;

  with del as (
    delete from public.whatsapp_conversations
    where is_group = true
      and lead_id is null
      and (last_message_at is null or last_message_at < now() - interval '30 days')
    returning id
  )
  select count(*) into deleted_convs from del;

  begin
    with del as (
      delete from public.media_jobs
      where status = 'done'
        and updated_at < now() - interval '30 days'
      returning id
    )
    select count(*) into deleted_jobs from del;
  exception when undefined_table or undefined_column then
    deleted_jobs := 0;
  end;

  begin
    with del as (
      delete from public.meta_webhook_events
      where coalesce(received_at, processed_at, next_retry_at, now()) < now() - interval '30 days'
      returning id
    )
    select count(*) into deleted_meta from del;
  exception when undefined_table or undefined_column then
    deleted_meta := 0;
  end;

  raise notice 'whatsapp retention: mensagens=% conversas=% media_jobs=% meta_events=%',
    deleted_msgs, deleted_convs, deleted_jobs, deleted_meta;
end;
$$;


ALTER FUNCTION "public"."cleanup_whatsapp_retention"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_automation_event"("p_event_id" "uuid", "p_worker_id" "text") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  with changed as (
    update public.automation_event_outbox
    set status = 'completed', completed_at = now(), locked_at = null,
        locked_by = null,
        last_error = case when payload ? 'runtime_decisions' then last_error else null end,
        updated_at = now()
    where id = p_event_id and status = 'processing' and locked_by = left(coalesce(p_worker_id, 'worker'), 200)
    returning id
  ) select exists(select 1 from changed);
$$;


ALTER FUNCTION "public"."complete_automation_event"("p_event_id" "uuid", "p_worker_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."copy_default_dre_groups"("org_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_group_id uuid;
begin
  if org_id is null then
    raise exception 'org_id is required';
  end if;

  if not public.is_super_admin()
     and not (public.get_user_organization_id() = org_id and public.is_admin()) then
    raise exception 'Usuário sem permissão para configurar DRE';
  end if;

  insert into public.dre_account_groups (organization_id, name, group_type, display_order, is_system)
  values
    (org_id, 'Vendas e comissões recebidas', 'revenue', 10, true),
    (org_id, 'Deduções e estornos', 'deduction', 20, true),
    (org_id, 'Custos operacionais', 'cost', 30, true),
    (org_id, 'Despesas administrativas', 'expense', 40, true),
    (org_id, 'Despesas financeiras', 'financial_expense', 50, true),
    (org_id, 'Receitas financeiras', 'financial_revenue', 60, true),
    (org_id, 'Impostos sobre lucro', 'tax', 70, true)
  on conflict do nothing;

  select id into v_group_id
  from public.dre_account_groups
  where organization_id = org_id and group_type = 'revenue'
  order by display_order
  limit 1;

  if v_group_id is not null then
    insert into public.dre_account_mappings (organization_id, group_id, category, entry_type)
    values
      (org_id, v_group_id, 'Comissões', 'receivable'),
      (org_id, v_group_id, 'Vendas', 'receivable'),
      (org_id, v_group_id, 'Receita', 'receivable')
    on conflict (organization_id, category, entry_type) do nothing;
  end if;

  select id into v_group_id
  from public.dre_account_groups
  where organization_id = org_id and group_type = 'expense'
  order by display_order
  limit 1;

  if v_group_id is not null then
    insert into public.dre_account_mappings (organization_id, group_id, category, entry_type)
    values
      (org_id, v_group_id, 'Marketing', 'payable'),
      (org_id, v_group_id, 'Administrativo', 'payable'),
      (org_id, v_group_id, 'Operacional', 'payable')
    on conflict (organization_id, category, entry_type) do nothing;
  end if;
end;
$$;


ALTER FUNCTION "public"."copy_default_dre_groups"("org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."count_unique_sessions"("p_organization_id" "uuid", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone) RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_org_id uuid;
  v_count bigint;
BEGIN
  v_user_org_id := public.get_user_organization_id();

  IF NOT public.is_super_admin()
     AND (v_user_org_id IS NULL OR p_organization_id IS DISTINCT FROM v_user_org_id) THEN
    RAISE EXCEPTION 'Not allowed to count sessions for this organization' USING ERRCODE = '42501';
  END IF;

  SELECT COUNT(DISTINCT le.session_id)::bigint
    INTO v_count
  FROM public.lead_events le
  WHERE le.organization_id = p_organization_id
    AND le.session_id IS NOT NULL
    AND le.created_at >= p_date_from
    AND le.created_at <= p_date_to;

  RETURN COALESCE(v_count, 0);
END;
$$;


ALTER FUNCTION "public"."count_unique_sessions"("p_organization_id" "uuid", "p_date_from" timestamp with time zone, "p_date_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_commission_on_won"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_commission_percentage numeric;
  v_commission_amount numeric;
  v_property_commission numeric;
  v_org_commission numeric;
begin
  if new.deal_status = 'won'
     and old.deal_status is distinct from 'won'
     and coalesce(new.valor_interesse, 0) > 0 then

    if new.assigned_user_id is not null
       and not exists (
         select 1
         from public.commissions
         where organization_id = new.organization_id
           and lead_id = new.id
       ) then
      select commission_percentage
      into v_property_commission
      from public.properties
      where organization_id = new.organization_id
        and id = new.property_id;

      select default_commission_percentage
      into v_org_commission
      from public.organizations
      where id = new.organization_id;

      v_commission_percentage := coalesce(
        nullif(new.commission_percentage, 0),
        nullif(v_property_commission, 0),
        nullif(v_org_commission, 0),
        5.0
      );
      v_commission_amount := new.valor_interesse * (v_commission_percentage / 100);

      insert into public.commissions (
        organization_id, lead_id, user_id, property_id,
        base_value, amount, percentage, status, notes
      ) values (
        new.organization_id, new.id, new.assigned_user_id, new.property_id,
        new.valor_interesse, v_commission_amount, v_commission_percentage,
        'forecast', 'Comissao gerada automaticamente'
      );
    end if;

    if not exists (
      select 1
      from public.financial_entries
      where organization_id = new.organization_id
        and lead_id = new.id
        and type = 'receivable'
    ) then
      insert into public.financial_entries (
        organization_id, lead_id, type, amount,
        due_date, status, description
      ) values (
        new.organization_id, new.id, 'receivable', new.valor_interesse,
        (current_date + interval '30 days')::date,
        'pending', 'Venda - ' || new.name
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."create_commission_on_won"() OWNER TO "postgres";


