CREATE OR REPLACE FUNCTION "public"."create_initial_entry_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  INSERT INTO public.lead_entry_events (
    lead_id, organization_id, entry_type, source, property_id,
    valor_interesse, pipeline_id, stage_id, created_at
  ) VALUES (
    NEW.id, NEW.organization_id, 'initial', NEW.source,
    COALESCE(NEW.interest_property_id, NEW.property_id),
    NEW.valor_interesse, NEW.pipeline_id, NEW.stage_id, NEW.created_at
  );
  RETURN NEW;
END;
$$;


