CREATE OR REPLACE FUNCTION "public"."on_lead_created_entry_event"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.lead_entry_events (lead_id, organization_id, entry_type, source, created_at)
  VALUES (NEW.id, NEW.organization_id, 'initial', NEW.source, NEW.created_at);
  RETURN NEW;
END;
$$;


