CREATE OR REPLACE FUNCTION "public"."pick_round_robin_for_lead"("p_lead_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'private', 'pg_temp'
    AS $$
declare
  selected_queue_id uuid;
begin
  with lead_context as (
    select
      lead.*,
      lead_meta.form_id as lead_meta_form_id,
      lead_meta.campaign_name as lead_meta_campaign_name
    from public.leads as lead
    left join public.lead_meta as lead_meta
      on lead_meta.lead_id = lead.id
     and lead_meta.organization_id = lead.organization_id
    where lead.id = p_lead_id
    limit 1
  )
  select queue.id
  into selected_queue_id
  from lead_context as lead
  join public.round_robins as queue
    on queue.organization_id = lead.organization_id
   and coalesce(queue.is_active, true) = true
   and (queue.pipeline_id is null or queue.pipeline_id = lead.pipeline_id)
  cross join lateral (
    select exists (
      select 1
      from public.round_robin_rules as rule
      where rule.organization_id = queue.organization_id
        and rule.round_robin_id = queue.id
        and coalesce(rule.is_active, true) = true
    ) as has_rules
  ) as rule_state
  left join lateral (
    select max(coalesce(rule.priority, 0)) as matched_priority
    from public.round_robin_rules as rule
    cross join lateral (
      select
        lower(coalesce(nullif(rule.match_type, ''), rule.conditions->>'match_type', rule.name, '')) as match_type,
        coalesce(nullif(rule.match_value, ''), rule.conditions->>'match_value', '') as match_value
    ) as normalized
    cross join lateral (
      select array(
        select lower(btrim(value))
        from unnest(string_to_array(coalesce(normalized.match_value, ''), ',')) as value
        where btrim(value) <> ''
      ) as values
    ) as match_values
    where rule.organization_id = queue.organization_id
      and rule.round_robin_id = queue.id
      and coalesce(rule.is_active, true) = true
      and (
        normalized.match_type in ('all', 'any')
        or (
          normalized.match_type = 'source'
          and lower(coalesce(lead.source, '')) = any(match_values.values)
        )
        or (
          normalized.match_type in ('property', 'interest_property')
          and exists (
            select 1
            from unnest(match_values.values) as value
            where private.safe_uuid(value) = coalesce(lead.interest_property_id, lead.property_id)
          )
        )
        or (
          normalized.match_type = 'tag'
          and exists (
            select 1
            from public.lead_tags as lead_tag
            join unnest(match_values.values) as value
              on private.safe_uuid(value) = lead_tag.tag_id
            where lead_tag.organization_id = lead.organization_id
              and lead_tag.lead_id = lead.id
          )
        )
        or (
          normalized.match_type in ('meta_form', 'form')
          and lower(coalesce(lead.meta_form_id, lead.lead_meta_form_id, '')) = any(match_values.values)
        )
        or (
          normalized.match_type = 'webhook'
          and exists (
            select 1
            from unnest(match_values.values) as value
            where private.safe_uuid(value) = lead.source_webhook_id
          )
        )
        or (
          normalized.match_type = 'whatsapp_session'
          and lower(coalesce(lead.source_session_id::text, '')) = any(match_values.values)
        )
        or (
          normalized.match_type = 'city'
          and lower(coalesce(lead.cidade, '')) = any(match_values.values)
        )
        or (
          normalized.match_type = 'website_category'
          and lower(coalesce(lead.metadata->>'website_category', lead.source_detail, '')) = any(match_values.values)
        )
        or (
          normalized.match_type = 'campaign_contains'
          and exists (
            select 1
            from unnest(match_values.values) as value
            where lower(coalesce(lead.utm_campaign, lead.lead_meta_campaign_name, lead.meta_campaign_id, '')) like '%' || value || '%'
          )
        )
      )
  ) as matched_rule on true
  where matched_rule.matched_priority is not null
     or not rule_state.has_rules
  order by
    (matched_rule.matched_priority is null) asc,
    (queue.pipeline_id is null) asc,
    matched_rule.matched_priority desc nulls last,
    queue.created_at asc,
    queue.id asc
  limit 1;

  return selected_queue_id;
end;
$$;


ALTER FUNCTION "public"."pick_round_robin_for_lead"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_property_code_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.code IS DISTINCT FROM OLD.code
     AND coalesce(auth.role(), '') <> 'service_role'
  THEN
    RAISE EXCEPTION 'Property code cannot be changed after creation'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."prevent_property_code_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_automation_inbound_message"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid", "p_message_type" "text", "p_content" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  candidate record;
  wait_step record;
  normalized_type text := lower(trim(coalesce(p_message_type, 'text')));
  normalized_content text := lower(trim(coalesce(p_content, '')));
  expected_keywords jsonb;
  keyword text;
  keyword_matched boolean;
  handoff_reason text;
  burst_limit integer;
  recent_message_count integer;
  resume_result jsonb;
  resumed_ids uuid[] := array[]::uuid[];
  cancelled_ids uuid[] := array[]::uuid[];
  target_user_id uuid;
  target_lead_name text;
  preview text;
begin
  if p_organization_id is null or p_lead_id is null or p_message_id is null or p_occurred_at is null then
    return jsonb_build_object('ok', false, 'status', 'invalid_input');
  end if;

  preview := left(coalesce(nullif(trim(p_content), ''), '[' || normalized_type || ']'), 300);

  for candidate in
    select
      e.id,
      e.conversation_id,
      e.current_node_key,
      e.next_execution_at,
      fv.created_by,
      coalesce((
        select node->'config'
        from jsonb_array_elements(coalesce(fv.graph->'nodes', '[]'::jsonb)) node
        where node->>'id' = e.current_node_key and node->>'type' = 'delay'
        limit 1
      ), '{}'::jsonb) as wait_config,
      l.assigned_user_id,
      l.name as lead_name
    from public.automation_executions e
    join public.automation_flow_versions fv
      on fv.id = e.flow_version_id
     and fv.organization_id = e.organization_id
     and fv.requires_review = false
    join public.leads l
      on l.id = e.lead_id and l.organization_id = e.organization_id
    where e.organization_id = p_organization_id
      and e.lead_id = p_lead_id
      and e.status = 'waiting'
      and e.cancellation_requested_at is null
      and (e.conversation_id is null or p_conversation_id is null or e.conversation_id = p_conversation_id)
    order by e.started_at, e.id
  loop
    if not coalesce((candidate.wait_config->>'stop_on_reply')::boolean, false) then
      continue;
    end if;

    select s.id, s.started_at
    into wait_step
    from public.automation_execution_steps s
    where s.organization_id = p_organization_id
      and s.execution_id = candidate.id
      and s.node_key = candidate.current_node_key
      and s.status = 'waiting'
    order by s.attempt desc, s.started_at desc
    limit 1;

    if wait_step.id is null
       or p_occurred_at < wait_step.started_at
       or candidate.next_execution_at is null
       or p_occurred_at > candidate.next_execution_at then
      continue;
    end if;

    handoff_reason := null;
    burst_limit := greatest(coalesce(nullif(candidate.wait_config->>'handoff_after_message_burst', '')::integer, 3), 0);

    if normalized_type not in ('text', 'conversation', 'extendedtextmessage')
       and coalesce((candidate.wait_config->>'handoff_on_non_text')::boolean, true) then
      handoff_reason := 'automation_handoff_non_text:' || normalized_type;
    end if;

    if handoff_reason is null and burst_limit > 0 then
      select count(*)
      into recent_message_count
      from public.whatsapp_messages m
      where m.organization_id = p_organization_id
        and m.lead_id = p_lead_id
        and coalesce(m.from_me, false) = false
        and m.direction = 'inbound'
        and coalesce(m.received_at, m.created_at) >= p_occurred_at - interval '2 minutes'
        and coalesce(m.received_at, m.created_at) <= p_occurred_at + interval '2 minutes';
      if recent_message_count >= burst_limit then
        handoff_reason := 'automation_handoff_message_burst';
      end if;
    end if;

    if handoff_reason is null
       and normalized_type in ('text', 'conversation', 'extendedtextmessage')
       and lower(coalesce(candidate.wait_config->>'reply_match_mode', 'any_text')) = 'keywords' then
      expected_keywords := coalesce(candidate.wait_config->'expected_reply_keywords', '[]'::jsonb);
      keyword_matched := false;
      if jsonb_typeof(expected_keywords) = 'array' then
        for keyword in select lower(trim(value)) from jsonb_array_elements_text(expected_keywords)
        loop
          if keyword <> '' and position(keyword in normalized_content) > 0 then
            keyword_matched := true;
            exit;
          end if;
        end loop;
      end if;
      if not keyword_matched
         and coalesce((candidate.wait_config->>'handoff_on_unmatched_reply')::boolean, true) then
        handoff_reason := 'automation_handoff_unmatched_reply';
      end if;
    end if;

    target_user_id := coalesce(candidate.assigned_user_id, candidate.created_by);
    target_lead_name := coalesce(nullif(candidate.lead_name, ''), 'Lead');

    if handoff_reason is not null then
      if (select count(*) from unnest(private.cancel_lead_automation_executions(
        p_organization_id, p_lead_id, handoff_reason, p_conversation_id
      ))) > 0 then
        cancelled_ids := array_append(cancelled_ids, candidate.id);
        perform private.notify_automation_attention(
          p_organization_id,
          p_lead_id,
          target_user_id,
          'Automacao pausada: atendimento humano necessario',
          target_lead_name || ' enviou uma resposta fora do fluxo (' || preview || ').',
          'automation_handoff',
          'automation_handoff:' || p_message_id::text || ':' || target_user_id::text,
          jsonb_build_object(
            'reason', handoff_reason,
            'message_id', p_message_id,
            'conversation_id', p_conversation_id,
            'execution_id', candidate.id
          )
        );

        insert into public.lead_timeline_events (
          organization_id, lead_id, event_type, title, description,
          user_id, actor_user_id, metadata, event_at
        ) values (
          p_organization_id, p_lead_id,
          'automation_handoff',
          'Automacao pausada para atendimento humano', preview,
          target_user_id, target_user_id,
          jsonb_build_object(
            'reason', handoff_reason,
            'message_id', p_message_id,
            'conversation_id', p_conversation_id,
            'execution_id', candidate.id
          ),
          p_occurred_at
        );
      end if;
      exit;
    end if;

    resume_result := public.resume_automation_delay(
      p_organization_id,
      candidate.id,
      'replied',
      p_occurred_at,
      jsonb_build_object(
        'message_id', p_message_id,
        'message_type', normalized_type,
        'content', p_content,
        'conversation_id', p_conversation_id
      ),
      p_lead_id,
      p_conversation_id
    );

    if coalesce((resume_result->>'ok')::boolean, false) then
      resumed_ids := array_append(resumed_ids, candidate.id);
      perform private.notify_automation_attention(
        p_organization_id,
        p_lead_id,
        target_user_id,
        'Lead respondeu a automacao',
        target_lead_name || ' respondeu: ' || preview,
        'automation_reply',
        'automation_reply:' || p_message_id::text || ':' || target_user_id::text,
        jsonb_build_object(
          'message_id', p_message_id,
          'conversation_id', p_conversation_id,
          'execution_id', candidate.id
        )
      );
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'status', 'processed',
    'resumed_execution_ids', to_jsonb(resumed_ids),
    'cancelled_execution_ids', to_jsonb(cancelled_ids)
  );
end;
$$;


ALTER FUNCTION "public"."process_automation_inbound_message"("p_organization_id" "uuid", "p_lead_id" "uuid", "p_conversation_id" "uuid", "p_message_id" "uuid", "p_message_type" "text", "p_content" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_conversations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid",
    "lead_id" "uuid",
    "remote_jid" "text" NOT NULL,
    "contact_name" "text",
    "contact_phone" "text",
    "contact_picture" "text",
    "is_group" boolean DEFAULT false,
    "last_message" "text",
    "last_message_at" timestamp with time zone,
    "unread_count" integer DEFAULT 0,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "deleted_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "contact_presence" "text",
    "presence_updated_at" timestamp with time zone,
    "organization_id" "uuid",
    "last_message_received_at" timestamp with time zone,
    "assigned_user_id" "uuid",
    "last_message_preview" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL
)
WITH ("autovacuum_vacuum_scale_factor"='0.03', "autovacuum_analyze_scale_factor"='0.02', "autovacuum_vacuum_threshold"='500', "autovacuum_analyze_threshold"='500');


ALTER TABLE "public"."whatsapp_conversations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebind_whatsapp_conversation_session"("p_conversation_id" "uuid", "p_session_id" "uuid") RETURNS "public"."whatsapp_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_conversation public.whatsapp_conversations%ROWTYPE;
  v_session public.whatsapp_sessions%ROWTYPE;
  v_can_send boolean := false;
  v_can_access_lead boolean := false;
BEGIN
  SELECT *
  INTO v_conversation
  FROM public.whatsapp_conversations
  WHERE id = p_conversation_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Conversa WhatsApp não encontrada';
  END IF;

  SELECT *
  INTO v_session
  FROM public.whatsapp_sessions
  WHERE id = p_session_id
    AND status = 'connected';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sessão WhatsApp conectada não encontrada';
  END IF;

  IF v_conversation.organization_id IS NOT NULL
     AND v_session.organization_id IS NOT NULL
     AND v_conversation.organization_id <> v_session.organization_id THEN
    RAISE EXCEPTION 'Conversa e sessão pertencem a organizações diferentes';
  END IF;

  v_can_send :=
    public.is_super_admin()
    OR v_session.owner_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.whatsapp_session_access access
      WHERE access.session_id = v_session.id
        AND access.user_id = auth.uid()
        AND access.can_send = true
    );

  IF NOT v_can_send THEN
    RAISE EXCEPTION 'Usuário sem permissão para enviar por esta sessão';
  END IF;

  IF v_conversation.lead_id IS NOT NULL THEN
    v_can_access_lead := public.can_access_lead(v_conversation.lead_id, auth.uid());
  END IF;

  IF v_conversation.session_id IS NOT NULL
     AND v_conversation.session_id <> p_session_id
     AND NOT v_can_access_lead
     AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'Usuário sem permissão para religar esta conversa';
  END IF;

  UPDATE public.whatsapp_conversations
  SET
    session_id = p_session_id,
    organization_id = v_session.organization_id,
    updated_at = now()
  WHERE id = p_conversation_id
  RETURNING * INTO v_conversation;

  RETURN v_conversation;
END;
$$;


ALTER FUNCTION "public"."rebind_whatsapp_conversation_session"("p_conversation_id" "uuid", "p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebind_whatsapp_conversation_session"("p_conversation_id" "uuid", "p_session_id" "uuid", "p_remote_jid" "text" DEFAULT NULL::"text") RETURNS "public"."whatsapp_conversations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_source public.whatsapp_conversations%ROWTYPE;
  v_target public.whatsapp_conversations%ROWTYPE;
  v_session public.whatsapp_sessions%ROWTYPE;
  v_result public.whatsapp_conversations%ROWTYPE;
  v_can_send boolean := false;
  v_can_access_lead boolean := false;
  v_remote_jid text;
  v_phone_digits text;
  v_phone_local text;
  v_phone_without_country text;
  v_phone_without_ninth text;
  v_phone_with_ninth text;
  v_is_group boolean := false;
  v_is_lid boolean := false;
  v_is_newsletter boolean := false;
  v_has_real_phone boolean := false;
  v_matched_lead_id uuid;
BEGIN
  SELECT *
  INTO v_source
  FROM public.whatsapp_conversations
  WHERE id = p_conversation_id
    AND deleted_at IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'WhatsApp conversation not found';
  END IF;

  SELECT *
  INTO v_session
  FROM public.whatsapp_sessions
  WHERE id = p_session_id
    AND status = 'connected';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Connected WhatsApp session not found';
  END IF;

  IF v_source.organization_id IS NOT NULL
     AND v_session.organization_id IS NOT NULL
     AND v_source.organization_id <> v_session.organization_id THEN
    RAISE EXCEPTION 'Conversation and session belong to different organizations';
  END IF;

  v_can_send :=
    public.is_super_admin()
    OR v_session.owner_user_id = auth.uid()
    OR EXISTS (
      SELECT 1
      FROM public.whatsapp_session_access access
      WHERE access.session_id = v_session.id
        AND access.user_id = auth.uid()
        AND access.can_send = true
    );

  IF NOT v_can_send THEN
    RAISE EXCEPTION 'User cannot send through this WhatsApp session';
  END IF;

  IF v_source.lead_id IS NOT NULL THEN
    v_can_access_lead := public.can_access_lead(v_source.lead_id, auth.uid());
  END IF;

  IF v_source.session_id IS NOT NULL
     AND v_source.session_id <> p_session_id
     AND NOT v_can_access_lead
     AND NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'User cannot rebind this conversation';
  END IF;

  v_remote_jid := COALESCE(NULLIF(p_remote_jid, ''), v_source.remote_jid);
  v_is_group := COALESCE(v_source.is_group, false) OR v_remote_jid LIKE '%@g.us';
  v_is_lid := v_remote_jid LIKE '%@lid';
  v_is_newsletter := v_remote_jid LIKE '%@newsletter';
  v_phone_digits := regexp_replace(COALESCE(v_source.contact_phone, v_remote_jid, ''), '\D', '', 'g');
  v_phone_without_country := CASE
    WHEN v_phone_digits LIKE '55%' AND length(v_phone_digits) >= 12 THEN substring(v_phone_digits from 3)
    ELSE v_phone_digits
  END;
  v_phone_local := v_phone_without_country;
  v_phone_without_ninth := CASE
    WHEN length(v_phone_local) = 11 AND substring(v_phone_local from 3 for 1) = '9'
      THEN substring(v_phone_local from 1 for 2) || substring(v_phone_local from 4)
    ELSE NULL
  END;
  v_phone_with_ninth := CASE
    WHEN length(v_phone_local) = 10
      THEN substring(v_phone_local from 1 for 2) || '9' || substring(v_phone_local from 3)
    ELSE NULL
  END;
  v_has_real_phone := NOT v_is_group
    AND NOT v_is_lid
    AND NOT v_is_newsletter
    AND length(v_phone_digits) BETWEEN 10 AND 13;

  IF NOT v_is_group THEN
    IF v_source.lead_id IS NOT NULL THEN
      v_matched_lead_id := v_source.lead_id;
    ELSIF v_has_real_phone THEN
      SELECT l.id
      INTO v_matched_lead_id
      FROM public.leads l
      WHERE l.organization_id = v_session.organization_id
        AND l.phone IS NOT NULL
        AND (
          regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g') IN (
            v_phone_digits,
            v_phone_without_country,
            '55' || v_phone_without_country,
            COALESCE(v_phone_without_ninth, ''),
            CASE WHEN v_phone_without_ninth IS NOT NULL THEN '55' || v_phone_without_ninth ELSE '' END,
            COALESCE(v_phone_with_ninth, ''),
            CASE WHEN v_phone_with_ninth IS NOT NULL THEN '55' || v_phone_with_ninth ELSE '' END
          )
          OR right(regexp_replace(COALESCE(l.phone, ''), '\D', '', 'g'), 8) = right(v_phone_digits, 8)
        )
      ORDER BY l.updated_at DESC NULLS LAST, l.created_at DESC
      LIMIT 1;
    END IF;
  END IF;

  SELECT c.*
  INTO v_target
  FROM public.whatsapp_conversations c
  WHERE c.organization_id = v_session.organization_id
    AND c.deleted_at IS NULL
    AND c.id <> p_conversation_id
    AND COALESCE(c.is_group, false) = v_is_group
    AND (
      (NOT v_is_group AND v_matched_lead_id IS NOT NULL AND c.lead_id = v_matched_lead_id)
      OR (
        NOT v_is_group
        AND v_has_real_phone
        AND (
          regexp_replace(COALESCE(c.contact_phone, c.remote_jid, ''), '\D', '', 'g') IN (
            v_phone_digits,
            v_phone_without_country,
            '55' || v_phone_without_country,
            COALESCE(v_phone_without_ninth, ''),
            CASE WHEN v_phone_without_ninth IS NOT NULL THEN '55' || v_phone_without_ninth ELSE '' END,
            COALESCE(v_phone_with_ninth, ''),
            CASE WHEN v_phone_with_ninth IS NOT NULL THEN '55' || v_phone_with_ninth ELSE '' END
          )
          OR right(regexp_replace(COALESCE(c.contact_phone, c.remote_jid, ''), '\D', '', 'g'), 8) = right(v_phone_digits, 8)
        )
      )
      OR (
        c.session_id = p_session_id
        AND c.remote_jid = v_remote_jid
      )
    )
  ORDER BY
    CASE WHEN NOT v_is_group AND v_matched_lead_id IS NOT NULL AND c.lead_id = v_matched_lead_id THEN 0 ELSE 1 END,
    CASE WHEN c.session_id = p_session_id THEN 0 ELSE 1 END,
    c.last_message_at DESC NULLS LAST,
    c.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    UPDATE public.whatsapp_messages m
    SET conversation_id = v_target.id
    WHERE m.conversation_id = v_source.id
      AND NOT EXISTS (
        SELECT 1
        FROM public.whatsapp_messages existing
        WHERE existing.conversation_id = v_target.id
          AND existing.message_id = m.message_id
          AND existing.message_id IS NOT NULL
      );

    DELETE FROM public.whatsapp_messages m
    WHERE m.conversation_id = v_source.id
      AND EXISTS (
        SELECT 1
        FROM public.whatsapp_messages existing
        WHERE existing.conversation_id = v_target.id
          AND existing.message_id = m.message_id
          AND existing.message_id IS NOT NULL
          AND existing.id <> m.id
      );

    UPDATE public.whatsapp_conversations
    SET
      session_id = NULL,
      deleted_at = now(),
      updated_at = now()
    WHERE id = v_source.id;

    UPDATE public.whatsapp_conversations
    SET
      organization_id = COALESCE(v_target.organization_id, v_session.organization_id),
      session_id = p_session_id,
      lead_id = CASE
        WHEN v_is_group THEN NULL
        ELSE COALESCE(v_target.lead_id, v_source.lead_id, v_matched_lead_id)
      END,
      remote_jid = CASE
        WHEN v_is_group THEN v_remote_jid
        WHEN v_is_lid OR v_is_newsletter THEN v_target.remote_jid
        ELSE COALESCE(NULLIF(v_target.remote_jid, ''), v_remote_jid)
      END,
      contact_name = COALESCE(NULLIF(v_target.contact_name, ''), NULLIF(v_source.contact_name, ''), v_target.contact_name),
      contact_phone = CASE
        WHEN v_is_group THEN NULL
        WHEN v_has_real_phone THEN COALESCE(NULLIF(v_target.contact_phone, ''), v_phone_digits)
        ELSE v_target.contact_phone
      END,
      contact_picture = COALESCE(v_target.contact_picture, v_source.contact_picture),
      last_message = CASE
        WHEN v_target.last_message_at IS NULL THEN v_source.last_message
        WHEN v_source.last_message_at IS NULL THEN v_target.last_message
        WHEN v_source.last_message_at > v_target.last_message_at THEN v_source.last_message
        ELSE v_target.last_message
      END,
      last_message_at = GREATEST(v_target.last_message_at, v_source.last_message_at),
      updated_at = now()
    WHERE id = v_target.id
    RETURNING * INTO v_result;

    RETURN v_result;
  END IF;

  UPDATE public.whatsapp_conversations
  SET
    session_id = p_session_id,
    organization_id = v_session.organization_id,
    remote_jid = v_remote_jid,
    lead_id = CASE
      WHEN v_is_group THEN NULL
      ELSE COALESCE(lead_id, v_matched_lead_id)
    END,
    contact_phone = CASE
      WHEN v_is_group THEN NULL
      WHEN v_has_real_phone THEN COALESCE(NULLIF(contact_phone, ''), v_phone_digits)
      ELSE NULLIF(contact_phone, v_phone_digits)
    END,
    updated_at = now()
  WHERE id = p_conversation_id
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


ALTER FUNCTION "public"."rebind_whatsapp_conversation_session"("p_conversation_id" "uuid", "p_session_id" "uuid", "p_remote_jid" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."recover_stuck_executions"("p_stale_minutes" integer DEFAULT 10) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_count INT;
BEGIN
    WITH stuck AS (
        UPDATE public.automation_executions
        SET
            status = 'failed',
            error_message = 'Execução interrompida ou timeout (recuperado automaticamente)',
            completed_at = now(),
            lock_token = NULL,
            locked_at = NULL
        WHERE status = 'running'
          AND (
            (locked_at IS NOT NULL AND locked_at < now() - (p_stale_minutes || ' minutes')::interval)
            OR (locked_at IS NULL AND started_at < now() - (p_stale_minutes || ' minutes')::interval)
          )
        RETURNING id
    )
    SELECT count(*) INTO v_count FROM stuck;

    RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."recover_stuck_executions"("p_stale_minutes" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redistribute_lead_from_pool"("p_lead_id" "uuid", "p_reason" "text" DEFAULT 'timeout'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead public.leads%ROWTYPE;
  v_pipeline public.pipelines%ROWTYPE;
  v_assignment record;
  v_assignment_at timestamptz;
  v_old_user_id uuid;
  v_result jsonb;
  v_history_id uuid;
  v_has_blocking_activity boolean;
BEGIN
  SELECT * INTO v_lead
  FROM public.leads
  WHERE id = p_lead_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'reason', 'lead_not_found');
  END IF;

  v_old_user_id := v_lead.assigned_user_id;

  IF v_old_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_without_owner');
  END IF;

  IF lower(COALESCE(v_lead.deal_status, 'open')) IN ('won', 'ganho', 'lost', 'perdido', 'closed', 'fechado') THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'closed_deal_status');
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.stages s
    WHERE s.id = v_lead.stage_id
      AND (COALESCE(s.is_won, false) OR COALESCE(s.is_lost, false))
  ) THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'closed_stage');
  END IF;

  SELECT * INTO v_pipeline
  FROM public.pipelines p
  WHERE p.id = v_lead.pipeline_id
    AND COALESCE(p.pool_enabled, false) = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'pool_disabled_for_pipeline');
  END IF;

  SELECT al.* INTO v_assignment
  FROM public.assignments_log al
  WHERE al.lead_id = p_lead_id
    AND al.assigned_user_id = v_old_user_id
    AND al.round_robin_id IS NOT NULL
    AND COALESCE(al.reason, '') IN ('round_robin_auto', 'round_robin')
  ORDER BY COALESCE(al.assigned_at, al.created_at) DESC, al.created_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_not_assigned_by_distribution_queue');
  END IF;

  v_assignment_at := COALESCE(v_assignment.assigned_at, v_assignment.created_at, v_lead.assigned_at, v_lead.created_at);

  IF v_pipeline.pool_enabled_at IS NOT NULL AND v_assignment_at < v_pipeline.pool_enabled_at THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_assigned_before_pool_enabled');
  END IF;

  v_has_blocking_activity := false;

  IF v_lead.first_response_at IS NOT NULL AND v_lead.first_response_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.first_touch_at IS NOT NULL AND v_lead.first_touch_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.owner_last_activity_at IS NOT NULL AND v_lead.owner_last_activity_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.last_contact_at IS NOT NULL AND v_lead.last_contact_at >= v_assignment_at - interval '5 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_lead.stage_entered_at IS NOT NULL AND v_lead.stage_entered_at > v_assignment_at + interval '10 seconds' THEN
    v_has_blocking_activity := true;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.lead_timeline_events e
    WHERE e.lead_id = p_lead_id
      AND e.created_at >= v_assignment_at - interval '5 seconds'
      AND e.event_type NOT IN ('lead_created', 'lead_assigned')
  ) THEN
    v_has_blocking_activity := true;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.whatsapp_messages wm
    WHERE wm.lead_id = p_lead_id
      AND wm.created_at >= v_assignment_at - interval '5 seconds'
      AND (COALESCE(wm.from_me, false) = true OR wm.sender_user_id IS NOT NULL)
  ) THEN
    v_has_blocking_activity := true;
  END IF;

  IF v_has_blocking_activity THEN
    RETURN jsonb_build_object('success', false, 'skipped', true, 'lead_id', p_lead_id, 'reason', 'lead_has_activity_after_distribution');
  END IF;

  INSERT INTO public.lead_pool_history (lead_id, organization_id, from_user_id, reason)
  VALUES (p_lead_id, v_lead.organization_id, v_old_user_id, p_reason)
  RETURNING id INTO v_history_id;

  UPDATE public.leads
  SET assigned_user_id = NULL,
      assigned_at = NULL,
      redistribution_count = COALESCE(redistribution_count, 0) + 1,
      last_redistributed_at = now(),
      redistribution_warning_sent_at = NULL,
      updated_at = now()
  WHERE id = p_lead_id;

  SELECT public.handle_lead_intake(p_lead_id) INTO v_result;

  IF v_result->>'assigned_user_id' IS NOT NULL THEN
    UPDATE public.lead_pool_history
    SET to_user_id = (v_result->>'assigned_user_id')::uuid
    WHERE id = v_history_id;
  END IF;

  IF v_old_user_id IS NOT NULL THEN
    PERFORM public.create_notification(
      v_old_user_id,
      v_lead.organization_id,
      'Lead redistribuído',
      'O lead "' || COALESCE(v_lead.name, 'sem nome') || '" foi redistribuído por inatividade.',
      'warning',
      p_lead_id
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'lead_id', p_lead_id,
    'from_user_id', v_old_user_id,
    'to_user_id', v_result->>'assigned_user_id',
    'redistribution_count', COALESCE(v_lead.redistribution_count, 0) + 1
  );
END;
$$;


ALTER FUNCTION "public"."redistribute_lead_from_pool"("p_lead_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."redistribute_lead_round_robin"("p_lead_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_previous_assigned_user_id uuid;
  v_transfer_result public.leads;
  v_distribution_result jsonb;
BEGIN
  SELECT assigned_user_id
  INTO v_previous_assigned_user_id
  FROM public.leads
  WHERE id = p_lead_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lead not found';
  END IF;

  SELECT *
  INTO v_transfer_result
  FROM public.transfer_lead_assignee(p_lead_id, NULL);

  SELECT public.handle_lead_intake(p_lead_id)
  INTO v_distribution_result;

  RETURN jsonb_build_object(
    'previous_assigned_user_id', v_previous_assigned_user_id,
    'lead_id', p_lead_id,
    'distribution_result', v_distribution_result
  );
END;
$$;


ALTER FUNCTION "public"."redistribute_lead_round_robin"("p_lead_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_lead_reentry"("p_lead_id" "uuid", "p_org_id" "uuid", "p_entry_type" "text" DEFAULT 'reentry'::"text", "p_source" "text" DEFAULT NULL::"text", "p_campaign_name" "text" DEFAULT NULL::"text", "p_utm_source" "text" DEFAULT NULL::"text", "p_utm_medium" "text" DEFAULT NULL::"text", "p_utm_campaign" "text" DEFAULT NULL::"text", "p_property_id" "uuid" DEFAULT NULL::"uuid", "p_valor_interesse" numeric DEFAULT NULL::numeric, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
  -- Insere o evento de entrada
  INSERT INTO public.lead_entry_events (
    lead_id,
    organization_id,
    entry_type,
    source,
    campaign_name,
    utm_source,
    utm_medium,
    utm_campaign,
    property_id,
    valor_interesse,
    metadata
  ) VALUES (
    p_lead_id,
    p_org_id,
    p_entry_type,
    p_source,
    p_campaign_name,
    p_utm_source,
    p_utm_medium,
    p_utm_campaign,
    p_property_id,
    p_valor_interesse,
    p_metadata
  );

  -- Atualiza contadores e metadados no lead
  UPDATE public.leads
  SET
    reentry_count = COALESCE(reentry_count, 0) + 1,
    last_entry_at = NOW(),
    source = COALESCE(p_source, source),
    interest_property_id = COALESCE(p_property_id, interest_property_id),
    valor_interesse = COALESCE(p_valor_interesse, valor_interesse)
  WHERE id = p_lead_id;
END;
$$;


ALTER FUNCTION "public"."register_lead_reentry"("p_lead_id" "uuid", "p_org_id" "uuid", "p_entry_type" "text", "p_source" "text", "p_campaign_name" "text", "p_utm_source" "text", "p_utm_medium" "text", "p_utm_campaign" "text", "p_property_id" "uuid", "p_valor_interesse" numeric, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_commissions_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.type = 'receivable'
     AND NEW.status = 'paid'
     AND COALESCE(OLD.status,'') <> 'paid'
     AND NEW.contract_id IS NOT NULL THEN

    UPDATE public.commissions
       SET status = 'pending',
           updated_at = now()
     WHERE contract_id = NEW.contract_id
       AND status = 'forecast';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."release_commissions_on_payment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_due_automation_delays"("p_batch_size" integer DEFAULT 25) RETURNS SETOF "public"."automation_executions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  candidate record;
  resume_result jsonb;
begin
  for candidate in
    select e.id, e.organization_id
    from public.automation_executions e
    where e.status = 'waiting'
      and e.flow_version_id is not null
      and e.cancellation_requested_at is null
      and e.next_execution_at <= now()
      and exists (
        select 1 from public.organization_modules om
        where om.organization_id = e.organization_id
          and lower(trim(om.module_name)) = 'automations'
          and coalesce(om.is_enabled, false) = true
      )
    order by e.next_execution_at, e.id
    limit least(greatest(coalesce(p_batch_size, 25), 1), 100)
    for update skip locked
  loop
    resume_result := public.resume_automation_delay(
      candidate.organization_id,
      candidate.id,
      'elapsed',
      null,
      '{}'::jsonb,
      null,
      null
    );
    if coalesce((resume_result->>'ok')::boolean, false) then
      return query select e.* from public.automation_executions e where e.id = candidate.id;
    end if;
  end loop;
end;
$$;


ALTER FUNCTION "public"."release_due_automation_delays"("p_batch_size" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_execution_step_lock"("p_execution_id" "uuid", "p_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
    UPDATE public.automation_executions
    SET
        lock_token = NULL,
        locked_at = NULL
    WHERE id = p_execution_id AND lock_token = p_token;
END;
$$;


ALTER FUNCTION "public"."release_execution_step_lock"("p_execution_id" "uuid", "p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_stages"("p_stages" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_pipeline_id uuid;
  v_organization_id uuid;
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Authentication required';
  end if;

  if p_stages is null or jsonb_typeof(p_stages) <> 'array' or jsonb_array_length(p_stages) = 0 then
    raise exception 'Stages payload must be a non-empty array';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    where nullif(stage_item->>'id', '') is null
      or nullif(stage_item->>'pipeline_id', '') is null
      or nullif(btrim(stage_item->>'name'), '') is null
      or nullif(stage_item->>'position', '') is null
  ) then
    raise exception 'Each stage requires id, pipeline_id, name, and position';
  end if;

  select distinct (stage_item->>'pipeline_id')::uuid
    into v_pipeline_id
  from jsonb_array_elements(p_stages) as stage_item;

  if v_pipeline_id is null then
    raise exception 'Pipeline id is required';
  end if;

  if (
    select count(distinct stage_item->>'pipeline_id')
    from jsonb_array_elements(p_stages) as stage_item
  ) <> 1 then
    raise exception 'All stages must belong to the same pipeline';
  end if;

  select p.organization_id
    into v_organization_id
  from public.pipelines p
  where p.id = v_pipeline_id
    and p.organization_id = public.get_user_organization_id();

  if v_organization_id is null then
    raise exception 'Pipeline not found';
  end if;

  if not (
    public.is_admin()
    or public.user_has_permission('settings_pipelines', v_user_id)
    or (
      public.is_team_leader(v_user_id)
      and public.is_pipeline_in_led_team(v_pipeline_id, v_user_id)
    )
  ) then
    raise exception 'Insufficient permission to manage pipeline stages';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    group by (stage_item->>'position')::int
    having count(*) > 1
  ) then
    raise exception 'Stage positions must be unique';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_stages) as stage_item
    join public.stages s on s.id = (stage_item->>'id')::uuid
    where s.pipeline_id <> v_pipeline_id
  ) then
    raise exception 'Cannot move stages between pipelines';
  end if;

  with parked as (
    select
      id,
      (-1000000000 - row_number() over (order by position, id))::integer as temporary_position
    from public.stages
    where pipeline_id = v_pipeline_id
  )
  update public.stages s
  set position = parked.temporary_position
  from parked
  where s.id = parked.id;

  insert into public.stages (
    id,
    pipeline_id,
    organization_id,
    name,
    color,
    position,
    stage_key
  )
  select
    (stage_item->>'id')::uuid,
    v_pipeline_id,
    v_organization_id,
    nullif(btrim(stage_item->>'name'), ''),
    coalesce(nullif(stage_item->>'color', ''), '#6b7280'),
    (stage_item->>'position')::int,
    coalesce(
      nullif(btrim(stage_item->>'stage_key'), ''),
      regexp_replace(
        lower(nullif(btrim(stage_item->>'name'), '')),
        '[^a-z0-9]+',
        '_',
        'g'
      )
    )
  from jsonb_array_elements(p_stages) as stage_item
  on conflict (id) do update set
    pipeline_id = excluded.pipeline_id,
    organization_id = excluded.organization_id,
    name = excluded.name,
    color = excluded.color,
    position = excluded.position,
    stage_key = excluded.stage_key;
end;
$$;


ALTER FUNCTION "public"."reorder_stages"("p_stages" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reserve_automation_external_effect"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text", "p_lease_token" "text", "p_effect_key" "text", "p_effect_type" "text", "p_request" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  effect_id uuid;
  current_status text;
begin
  if not exists (
    select 1 from public.automation_executions e
    join public.organization_modules om
      on om.organization_id = e.organization_id
     and lower(trim(om.module_name)) = 'automations'
     and coalesce(om.is_enabled, false) = true
    where e.id = p_execution_id
      and e.organization_id = p_organization_id
      and e.current_node_key = p_node_key
      and e.locked_by = p_lease_token
      and e.status = 'running'
      and e.cancellation_requested_at is null
  ) then
    return jsonb_build_object('ok', false, 'execute', false, 'status', 'execution_not_running');
  end if;

  insert into public.automation_effect_dispatches (
    organization_id, execution_id, node_key, effect_key, effect_type, status, request
  ) values (
    p_organization_id, p_execution_id, p_node_key, p_effect_key, p_effect_type, 'sending', coalesce(p_request, '{}'::jsonb)
  ) on conflict (effect_key) do nothing
  returning id into effect_id;

  if effect_id is not null then
    return jsonb_build_object('ok', true, 'execute', true, 'status', 'sending', 'effect_id', effect_id);
  end if;

  select status into current_status
  from public.automation_effect_dispatches
  where effect_key = p_effect_key;
  return jsonb_build_object(
    'ok', current_status = 'succeeded',
    'execute', false,
    'status', coalesce(current_status, 'missing')
  );
end;
$$;


ALTER FUNCTION "public"."reserve_automation_external_effect"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text", "p_lease_token" "text", "p_effect_key" "text", "p_effect_type" "text", "p_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_gamification_season"("p_organization_id" "uuid", "p_season_name" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_caller_role text;
  v_caller_org uuid;
  v_new_season uuid;
  v_user record;
BEGIN
  SELECT role, organization_id INTO v_caller_role, v_caller_org
  FROM public.users WHERE id = auth.uid();

  IF v_caller_role NOT IN ('admin','super_admin') THEN
    RAISE EXCEPTION 'Apenas administradores podem reiniciar temporadas';
  END IF;

  IF v_caller_role <> 'super_admin' AND v_caller_org <> p_organization_id THEN
    RAISE EXCEPTION 'Sem permissão para esta organização';
  END IF;

  UPDATE public.gamification_seasons
     SET is_active = false, ended_at = now()
   WHERE organization_id = p_organization_id AND is_active = true;

  INSERT INTO public.gamification_seasons (
    organization_id, name, start_date, end_date, is_active,
    started_at, created_by, reset_reason
  ) VALUES (
    p_organization_id, COALESCE(NULLIF(trim(p_season_name),''), 'Nova Temporada'),
    CURRENT_DATE, CURRENT_DATE + INTERVAL '90 days', true,
    now(), auth.uid(), p_reason
  ) RETURNING id INTO v_new_season;

  UPDATE public.user_gamification_stats SET
    total_points     = 0,
    xp               = 0,
    xp_total         = 0,
    current_level    = 1,
    xp_current_level = 0,
    xp_next_level    = 100,
    rank_tier        = 'Bronze I',
    current_rank     = 'Bronze I',
    streak_days      = 0,
    season_id        = v_new_season,
    updated_at       = now()
  WHERE organization_id = p_organization_id;

  UPDATE public.user_mission_progress p SET
    current_count = 0,
    is_completed  = false,
    completed_at  = NULL,
    reset_at      = now(),
    updated_at    = now()
  FROM public.gamification_missions m
  WHERE p.mission_id = m.id
    AND m.organization_id = p_organization_id;

  FOR v_user IN
    SELECT id FROM public.users
    WHERE organization_id = p_organization_id AND COALESCE(is_active, true) = true
  LOOP
    INSERT INTO public.notifications (organization_id, user_id, type, title, content, is_read)
    VALUES (
      p_organization_id, v_user.id, 'gamification',
      '🏁 Nova temporada iniciada: ' || COALESCE(NULLIF(trim(p_season_name),''), 'Nova Temporada'),
      'Os níveis foram reiniciados. Hora de começar do zero e dominar o ranking!',
      false
    );
  END LOOP;

  RETURN v_new_season;
END;
$$;


ALTER FUNCTION "public"."reset_gamification_season"("p_organization_id" "uuid", "p_season_name" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_automation_whatsapp_conversation"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text", "p_lease_token" "text", "p_session_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_lead_id uuid;
  preferred_conversation_id uuid;
  existing_conversation_id uuid;
  target_name text;
  raw_phone text;
  phone_digits text;
  canonical_phone text;
  canonical_jid text;
begin
  select e.lead_id, e.conversation_id, l.name, nullif(l.phone, '')
  into target_lead_id, preferred_conversation_id, target_name, raw_phone
  from public.automation_executions e
  join public.leads l
    on l.id = e.lead_id and l.organization_id = e.organization_id
  join public.whatsapp_sessions ws
    on ws.id = p_session_id and ws.organization_id = e.organization_id
   and ws.status = 'connected'
   and coalesce(ws.is_active, true)
   and coalesce(ws.provider, 'evolution_go') = 'evolution_go'
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.current_node_key = p_node_key
    and e.status = 'running'
    and e.locked_by = p_lease_token
    and e.cancellation_requested_at is null
  for update of e;

  if target_lead_id is null then
    return jsonb_build_object('ok', false, 'status', 'execution_session_or_lead_unavailable');
  end if;

  phone_digits := regexp_replace(coalesce(raw_phone, ''), '[^0-9]', '', 'g');
  if length(phone_digits) between 10 and 15 then
    canonical_phone := case
      when left(phone_digits, 2) = '55' then phone_digits
      when length(phone_digits) in (10, 11) then '55' || phone_digits
      else phone_digits
    end;
    canonical_jid := canonical_phone || '@s.whatsapp.net';
  end if;

  select wc.id
  into existing_conversation_id
  from public.whatsapp_conversations wc
  where wc.organization_id = p_organization_id
    and wc.lead_id = target_lead_id
    and wc.session_id = p_session_id
    and wc.deleted_at is null
    and coalesce(wc.is_group, false) = false
  order by case when wc.id = preferred_conversation_id then 0 else 1 end,
           wc.last_message_at desc nulls last, wc.created_at desc, wc.id
  limit 1
  for update;

  if existing_conversation_id is null then
    if canonical_jid is null then
      return jsonb_build_object('ok', false, 'status', 'lead_has_no_valid_whatsapp_phone');
    end if;

    insert into public.whatsapp_conversations (
      organization_id, session_id, lead_id, assigned_user_id, remote_jid,
      contact_name, contact_phone, is_group, unread_count, metadata
    )
    select
      p_organization_id, p_session_id, target_lead_id, l.assigned_user_id,
      canonical_jid, coalesce(nullif(target_name, ''), canonical_phone),
      canonical_phone, false, 0,
      jsonb_build_object('origin', 'automation', 'execution_id', p_execution_id)
    from public.leads l
    where l.id = target_lead_id and l.organization_id = p_organization_id
    on conflict (session_id, remote_jid) do update
      set lead_id = coalesce(public.whatsapp_conversations.lead_id, excluded.lead_id),
          contact_name = coalesce(nullif(public.whatsapp_conversations.contact_name, ''), excluded.contact_name),
          contact_phone = coalesce(nullif(public.whatsapp_conversations.contact_phone, ''), excluded.contact_phone),
          deleted_at = null,
          archived_at = null,
          updated_at = now()
    returning id into existing_conversation_id;

    if not exists (
      select 1
      from public.whatsapp_conversations wc
      where wc.id = existing_conversation_id
        and wc.organization_id = p_organization_id
        and wc.lead_id = target_lead_id
        and wc.session_id = p_session_id
    ) then
      raise exception 'whatsapp_identity_belongs_to_another_lead';
    end if;
  end if;

  insert into public.whatsapp_contact_identity_aliases (
    organization_id, session_id, alias_jid, canonical_jid,
    contact_phone, lead_id, is_group, last_seen_at, metadata
  )
  select
    wc.organization_id, wc.session_id, wc.remote_jid, coalesce(canonical_jid, wc.remote_jid),
    coalesce(canonical_phone, wc.contact_phone), wc.lead_id, false, now(),
    jsonb_build_object('origin', 'automation', 'execution_id', p_execution_id)
  from public.whatsapp_conversations wc
  where wc.id = existing_conversation_id
  on conflict (organization_id, session_id, alias_jid) do update
    set canonical_jid = case
          when public.whatsapp_contact_identity_aliases.canonical_jid like '%@s.whatsapp.net'
            then public.whatsapp_contact_identity_aliases.canonical_jid
          else excluded.canonical_jid
        end,
        contact_phone = coalesce(excluded.contact_phone, public.whatsapp_contact_identity_aliases.contact_phone),
        lead_id = coalesce(excluded.lead_id, public.whatsapp_contact_identity_aliases.lead_id),
        last_seen_at = now(),
        metadata = public.whatsapp_contact_identity_aliases.metadata || excluded.metadata;

  update public.automation_executions e
  set conversation_id = existing_conversation_id,
      updated_at = now()
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.status = 'running'
    and e.locked_by = p_lease_token;

  return (
    select jsonb_build_object(
      'ok', true,
      'status', 'resolved',
      'id', wc.id,
      'session_id', wc.session_id,
      'lead_id', wc.lead_id,
      'remote_jid', coalesce((
        select alias.canonical_jid
        from public.whatsapp_contact_identity_aliases alias
        where alias.organization_id = wc.organization_id
          and alias.session_id = wc.session_id
          and alias.alias_jid = wc.remote_jid
          and alias.canonical_jid like '%@s.whatsapp.net'
        order by alias.last_seen_at desc
        limit 1
      ), wc.remote_jid),
      'is_group', wc.is_group
    )
    from public.whatsapp_conversations wc
    where wc.id = existing_conversation_id
  );
end;
$$;


ALTER FUNCTION "public"."resolve_automation_whatsapp_conversation"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_node_key" "text", "p_lease_token" "text", "p_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_site_domain"("p_domain" "text") RETURNS TABLE("organization_id" "uuid", "site_config" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_site organization_sites%ROWTYPE;
  v_org organizations%ROWTYPE;
  v_clean text;
  v_bare text;
BEGIN
  v_clean := lower(trim(p_domain));
  v_bare := regexp_replace(v_clean, '^www\.', '');

  SELECT * INTO v_site
  FROM organization_sites
  WHERE custom_domain IN (v_clean, v_bare, 'www.' || v_bare)
    AND domain_verified = true
    AND is_active = true
  LIMIT 1;

  IF v_site.id IS NULL THEN
    SELECT * INTO v_site
    FROM organization_sites
    WHERE subdomain = split_part(v_bare, '.', 1)
      AND is_active = true
    LIMIT 1;
  END IF;

  IF v_site.id IS NULL THEN
    RETURN;
  END IF;

  SELECT * INTO v_org FROM organizations WHERE id = v_site.organization_id;

  RETURN QUERY SELECT
    v_site.organization_id,
    jsonb_build_object(
      'id', v_site.id,
      'is_active', v_site.is_active,
      'subdomain', v_site.subdomain,
      'custom_domain', v_site.custom_domain,
      'site_title', COALESCE(v_site.site_title, v_org.name),
      'site_description', v_site.site_description,
      'logo_url', COALESCE(v_site.logo_url, v_org.logo_url),
      'favicon_url', v_site.favicon_url,
      'primary_color', v_site.primary_color,
      'secondary_color', v_site.secondary_color,
      'accent_color', v_site.accent_color,
      'site_theme', COALESCE(v_site.site_theme, 'dark'),
      'background_color', COALESCE(v_site.background_color, '#0D0D0D'),
      'text_color', COALESCE(v_site.text_color, '#FFFFFF'),
      'card_color', COALESCE(v_site.card_color, '#FFFFFF'),
      'whatsapp', v_site.whatsapp,
      'phone', v_site.phone,
      'email', v_site.email,
      'address', v_site.address,
      'city', v_site.city,
      'state', v_site.state,
      'instagram', v_site.instagram,
      'facebook', v_site.facebook,
      'youtube', v_site.youtube,
      'linkedin', v_site.linkedin,
      'about_title', v_site.about_title,
      'about_text', v_site.about_text,
      'about_image_url', v_site.about_image_url,
      'seo_title', v_site.seo_title,
      'seo_description', v_site.seo_description,
      'seo_keywords', v_site.seo_keywords,
      'google_analytics_id', v_site.google_analytics_id,
      'hero_image_url', v_site.hero_image_url,
      'hero_title', v_site.hero_title,
      'hero_subtitle', v_site.hero_subtitle,
      'page_banner_url', v_site.page_banner_url,
      'logo_width', COALESCE(v_site.logo_width, 160),
      'logo_height', COALESCE(v_site.logo_height, 50),
      'watermark_enabled', COALESCE(v_site.watermark_enabled, false),
      'watermark_opacity', COALESCE(v_site.watermark_opacity, 20),
      'watermark_logo_url', v_site.watermark_logo_url,
      'watermark_size', COALESCE(v_site.watermark_size, 80),
      'watermark_position', COALESCE(v_site.watermark_position, 'bottom-right'),
      'organization_name', v_org.name
    );
END;
$$;


ALTER FUNCTION "public"."resolve_site_domain"("p_domain" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resume_automation_delay"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_branch" "text", "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_reply_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_lead_id" "uuid" DEFAULT NULL::"uuid", "p_conversation_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  target_execution public.automation_executions%rowtype;
  target_graph jsonb;
  target_node jsonb;
  target_step_id uuid;
  wait_started_at timestamptz;
  target_node_key text;
  outgoing_count integer;
  is_reply_aware boolean;
  next_data jsonb;
  final_status text;
begin
  if p_branch not in ('replied', 'elapsed') then
    return jsonb_build_object('ok', false, 'status', 'invalid_branch');
  end if;

  select e.*
  into target_execution
  from public.automation_executions e
  join public.automation_flow_versions fv
    on fv.id = e.flow_version_id
   and fv.organization_id = e.organization_id
   and fv.requires_review = false
  where e.id = p_execution_id
    and e.organization_id = p_organization_id
    and e.status = 'waiting'
    and e.cancellation_requested_at is null
  for update of e;
  if not found then
    return jsonb_build_object('ok', false, 'status', 'not_waiting');
  end if;
  select fv.graph
  into target_graph
  from public.automation_flow_versions fv
  where fv.id = target_execution.flow_version_id
    and fv.organization_id = target_execution.organization_id
    and fv.requires_review = false;

  select node
  into target_node
  from jsonb_array_elements(coalesce(target_graph->'nodes', '[]'::jsonb)) node
  where node->>'id' = target_execution.current_node_key
    and node->>'type' = 'delay'
  limit 1;
  if target_node is null then
    raise exception 'waiting_execution_delay_node_missing';
  end if;
  is_reply_aware := coalesce((target_node->'config'->>'stop_on_reply')::boolean, false);

  select s.id, s.started_at
  into target_step_id, wait_started_at
  from public.automation_execution_steps s
  where s.execution_id = target_execution.id
    and s.organization_id = target_execution.organization_id
    and s.node_key = target_execution.current_node_key
    and s.status = 'waiting'
  order by s.attempt desc, s.started_at desc
  limit 1
  for update;
  if target_step_id is null then
    raise exception 'waiting_execution_step_missing';
  end if;

  if p_branch = 'replied' then
    if not is_reply_aware
       or (p_lead_id is not null and p_lead_id <> target_execution.lead_id)
       or (p_conversation_id is not null and target_execution.conversation_id is not null
         and p_conversation_id <> target_execution.conversation_id)
       or p_occurred_at is null
       or p_occurred_at < wait_started_at
       or p_occurred_at > target_execution.next_execution_at then
      return jsonb_build_object('ok', false, 'status', 'reply_outside_wait_window');
    end if;
  else
    if target_execution.next_execution_at is null or target_execution.next_execution_at > now() then
      return jsonb_build_object('ok', false, 'status', 'not_due');
    end if;
    -- A reply durably captured before the deadline wins even if the timeout
    -- worker races the event consumer. The event consumer will resume it.
    if is_reply_aware and exists (
      select 1
      from public.automation_event_outbox o
      where o.organization_id = target_execution.organization_id
        and o.lead_id = target_execution.lead_id
        and o.event_type = 'message_received'
        and o.status in ('pending', 'processing', 'failed')
        and (target_execution.conversation_id is null or o.conversation_id = target_execution.conversation_id)
        and private.safe_automation_timestamptz(o.payload->>'occurred_at') >= wait_started_at
        and private.safe_automation_timestamptz(o.payload->>'occurred_at') <= target_execution.next_execution_at
    ) then
      return jsonb_build_object('ok', false, 'status', 'reply_pending');
    end if;
  end if;

  select count(*)
  into outgoing_count
  from jsonb_array_elements(coalesce(target_graph->'connections', '[]'::jsonb)) edge
  where edge->>'source' = target_execution.current_node_key;

  select edge->>'target'
  into target_node_key
  from jsonb_array_elements(coalesce(target_graph->'connections', '[]'::jsonb)) edge
  where edge->>'source' = target_execution.current_node_key
    and (
      (is_reply_aware and coalesce(nullif(edge->>'condition_branch', ''), nullif(edge->>'source_handle', '')) =
        case when p_branch = 'replied' then 'replied' else 'no_reply' end)
      or (
        not is_reply_aware
        and coalesce(
          nullif(edge->>'condition_branch', ''),
          nullif(edge->>'source_handle', ''),
          'default'
        ) = 'default'
      )
    )
  limit 1;
  if outgoing_count > 0 and target_node_key is null then
    raise exception 'delay_branch_target_missing';
  end if;

  next_data := coalesce(target_execution.execution_data, '{}'::jsonb) - 'resume_branch';
  if p_branch = 'replied' then
    next_data := jsonb_set(next_data, '{reply_payload}', coalesce(p_reply_payload, '{}'::jsonb), true);
  end if;
  final_status := case when target_node_key is null then 'completed' else 'queued' end;

  update public.automation_execution_steps s
  set status = 'succeeded',
      output = coalesce(s.output, '{}'::jsonb) || jsonb_build_object(
        'branch', case when is_reply_aware then case when p_branch = 'replied' then 'replied' else 'no_reply' end else null end,
        'resume_reason', p_branch,
        'occurred_at', p_occurred_at,
        'next_node_key', target_node_key
      ),
      completed_at = now()
  where s.id = target_step_id and s.status = 'waiting';

  update public.automation_executions e
  set status = final_status,
      current_node_key = target_node_key,
      conversation_id = case
        when p_branch = 'replied' then coalesce(e.conversation_id, p_conversation_id)
        else e.conversation_id
      end,
      execution_data = next_data,
      next_execution_at = null,
      completed_at = case when final_status = 'completed' then now() else null end,
      locked_at = null,
      locked_by = null,
      updated_at = now()
  where e.id = target_execution.id and e.status = 'waiting';

  return jsonb_build_object(
    'ok', true,
    'status', final_status,
    'branch', case when is_reply_aware then case when p_branch = 'replied' then 'replied' else 'no_reply' end else null end,
    'next_node_key', target_node_key
  );
end;
$$;


ALTER FUNCTION "public"."resume_automation_delay"("p_organization_id" "uuid", "p_execution_id" "uuid", "p_branch" "text", "p_occurred_at" timestamp with time zone, "p_reply_payload" "jsonb", "p_lead_id" "uuid", "p_conversation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sanitize_whatsapp_message_metadata"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.metadata is not null then
    new.metadata = new.metadata - 'raw';

    if jsonb_typeof(new.metadata -> 'deletion_event') = 'object' then
      new.metadata = jsonb_set(
        new.metadata,
        '{deletion_event}',
        (new.metadata -> 'deletion_event') - 'raw',
        true
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sanitize_whatsapp_message_metadata"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_assigned_at"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  -- Se está sendo atribuído (antes era NULL ou mudou de usuário)
  IF NEW.assigned_user_id IS NOT NULL
     AND (OLD.assigned_user_id IS NULL OR OLD.assigned_user_id != NEW.assigned_user_id) THEN
    NEW.assigned_at := NOW();
    -- Limpar first_touch_at para novo ciclo de redistribuição
    NEW.first_touch_at := NULL;
  END IF;

  -- Se foi removido o responsável, limpar assigned_at
  IF NEW.assigned_user_id IS NULL AND OLD.assigned_user_id IS NOT NULL THEN
    NEW.assigned_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_lead_assigned_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_assigned_at_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  IF NEW.assigned_user_id IS NOT NULL THEN
    NEW.assigned_at := NOW();
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."set_lead_assigned_at_on_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_lead_timeline_event_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.event_at := coalesce(new.event_at, new.created_at, now());
  return new;
end;
$$;


ALTER FUNCTION "public"."set_lead_timeline_event_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_round_robin_member_organization_id"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.organization_id is null and new.round_robin_id is not null then
    select rr.organization_id
      into new.organization_id
      from public.round_robins rr
     where rr.id = new.round_robin_id;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."set_round_robin_member_organization_id"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_stage_organization_id_from_pipeline"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_pipeline_organization_id uuid;
begin
  if new.pipeline_id is null then
    return new;
  end if;

  select p.organization_id
    into v_pipeline_organization_id
  from public.pipelines p
  where p.id = new.pipeline_id;

  if v_pipeline_organization_id is null then
    raise exception 'Pipeline % not found for stage organization assignment', new.pipeline_id
      using errcode = 'foreign_key_violation';
  end if;

  if new.organization_id is null then
    new.organization_id := v_pipeline_organization_id;
  elsif new.organization_id <> v_pipeline_organization_id then
    raise exception 'Stage organization_id must match pipeline organization_id'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."set_stage_organization_id_from_pipeline"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_whatsapp_message_context"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  conversation_org_id uuid;
  conversation_lead_id uuid;
  conversation_session_id uuid;
  conversation_remote_jid text;
  session_org_id uuid;
begin
  if new.conversation_id is not null then
    select
      wc.organization_id,
      wc.lead_id,
      wc.session_id,
      wc.remote_jid
    into
      conversation_org_id,
      conversation_lead_id,
      conversation_session_id,
      conversation_remote_jid
    from public.whatsapp_conversations wc
    where wc.id = new.conversation_id;

    if conversation_org_id is null then
      raise exception 'whatsapp_messages.conversation_id_not_found';
    end if;

    if tg_op = 'UPDATE'
       and new.conversation_id is not distinct from old.conversation_id
       and new.session_id is not distinct from old.session_id then
      new.organization_id := old.organization_id;
      new.session_id := old.session_id;
    else
      new.organization_id := conversation_org_id;
      if new.session_id is null then
        new.session_id := conversation_session_id;
      end if;
    end if;

    if new.lead_id is null then
      new.lead_id := conversation_lead_id;
    end if;

    if new.remote_jid is null then
      new.remote_jid := conversation_remote_jid;
    end if;
  elsif new.organization_id is null and new.session_id is not null then
    select ws.organization_id
    into session_org_id
    from public.whatsapp_sessions ws
    where ws.id = new.session_id;

    new.organization_id := session_org_id;
  end if;

  if new.organization_id is null then
    raise exception 'whatsapp_messages.organization_id_required';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."set_whatsapp_message_context"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."set_whatsapp_message_context"() IS 'Derives safe WhatsApp message context while preserving immutable historical session provenance on non-transport updates.';



