CREATE OR REPLACE FUNCTION "public"."sync_telecom_customer_plan_value"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan_price numeric;
BEGIN
  -- Se plan_id foi definido/alterado e plan_value não foi informado, preencher com o preço do plano
  IF NEW.plan_id IS NOT NULL AND (NEW.plan_value IS NULL OR TG_OP = 'INSERT' OR OLD.plan_id IS DISTINCT FROM NEW.plan_id) THEN
    -- Se o plan_id mudou, atualiza o plan_value com o preço do plano
    IF TG_OP = 'INSERT' OR OLD.plan_id IS DISTINCT FROM NEW.plan_id THEN
      SELECT price INTO v_plan_price
      FROM service_plans
      WHERE id = NEW.plan_id;

      IF v_plan_price IS NOT NULL AND NEW.plan_value IS NULL THEN
        NEW.plan_value := v_plan_price;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."sync_telecom_customer_plan_value"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_telecom_customer_seller_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_lead_assigned_user_id uuid;
BEGIN
  -- Se seller_id não foi definido, buscar do lead correspondente pelo nome
  IF NEW.seller_id IS NULL THEN
    SELECT assigned_user_id INTO v_lead_assigned_user_id
    FROM leads
    WHERE organization_id = NEW.organization_id
      AND name = NEW.name
      AND assigned_user_id IS NOT NULL
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_lead_assigned_user_id IS NOT NULL THEN
      NEW.seller_id := v_lead_assigned_user_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


