CREATE OR REPLACE FUNCTION "public"."try_acquire_execution_step_lock"("p_execution_id" "uuid", "p_max_lock_age_seconds" integer DEFAULT 300) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_token TEXT;
    v_now TIMESTAMPTZ := now();
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.automation_executions
        WHERE id = p_execution_id AND status IN ('completed', 'failed', 'cancelled')
    ) THEN
        RETURN NULL;
    END IF;

    v_token := gen_random_uuid()::text;

    UPDATE public.automation_executions
    SET
        lock_token = v_token,
        locked_at = v_now,
        status = 'running'
    WHERE id = p_execution_id
      AND (
        lock_token IS NULL
        OR locked_at < v_now - (p_max_lock_age_seconds || ' seconds')::interval
      )
      AND status NOT IN ('completed', 'failed', 'cancelled');

    IF FOUND THEN
        RETURN v_token;
    ELSE
        RETURN NULL;
    END IF;
END;
$$;


ALTER FUNCTION "public"."try_acquire_execution_step_lock"("p_execution_id" "uuid", "p_max_lock_age_seconds" integer) OWNER TO "postgres";


