CREATE OR REPLACE FUNCTION "public"."vimob_can_access_whatsapp_conversation"("p_conversation_id" "uuid", "p_permission" "text" DEFAULT 'view'::"text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.whatsapp_conversations c
    WHERE c.id = p_conversation_id
      AND public.vimob_can_access_whatsapp_session(c.session_id, p_permission)
  );
$$;


