CREATE OR REPLACE FUNCTION "public"."whatsapp_webhook_has_lead_creation_context"("p_metadata" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(
    lower(btrim(
      p_metadata #>> '{whatsapp_attribution,source_referral,explicit_source_type}'
    )) = 'ad'
    and coalesce(
      nullif(btrim(p_metadata #>> '{whatsapp_attribution,ad_id}'), ''),
      nullif(btrim(p_metadata #>> '{whatsapp_attribution,source_id}'), ''),
      nullif(btrim(p_metadata #>> '{whatsapp_attribution,source_referral,source_id}'), '')
    ) ~ '^[0-9]{5,40}$',
    false
  );
$_$;


ALTER FUNCTION "public"."whatsapp_webhook_has_lead_creation_context"("p_metadata" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."whatsapp_webhook_has_lead_creation_context"("p_metadata" "jsonb") IS 'Allows automatic WhatsApp lead creation only for an explicit Meta ad referral with a numeric ad id; existing leads are unaffected.';



