CREATE TABLE IF NOT EXISTS "public"."gamification_missions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid",
    "title" "text" NOT NULL,
    "description" "text",
    "action_type" "text" NOT NULL,
    "target_count" integer NOT NULL,
    "bonus_points" integer NOT NULL,
    "period" "text" DEFAULT 'daily'::"text",
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "target_scope" "text" DEFAULT 'organization'::"text",
    "target_user_id" "uuid",
    "current_progress" integer DEFAULT 0,
    CONSTRAINT "gamification_missions_action_catalog_canonical_check" CHECK (((("is_active" = false) AND ("action_type" IS NULL)) OR ("action_type" = ANY (ARRAY['call_made'::"text", 'message_sent'::"text", 'contact_made'::"text", 'visit_scheduled'::"text", 'visit_confirmed'::"text", 'meeting_scheduled'::"text", 'meeting_held'::"text", 'proposal_sent'::"text", 'sale_closed'::"text", 'contract_signed'::"text", 'lost_lead_recovered'::"text", 'lead_created'::"text", 'lead_created_manual'::"text", 'property_created'::"text", 'prospecting_report'::"text"])))),
    CONSTRAINT "gamification_missions_values_canonical_check" CHECK (((("target_count" >= 1) AND ("target_count" <= 1000000)) AND (("bonus_points" >= 0) AND ("bonus_points" <= 1000000)) AND (COALESCE("period", 'season'::"text") = ANY (ARRAY['daily'::"text", 'weekly'::"text", 'monthly'::"text", 'season'::"text"])) AND ("target_scope" = ANY (ARRAY['organization'::"text", 'user'::"text"])) AND (("target_scope" <> 'user'::"text") OR ("target_user_id" IS NOT NULL))))
);


ALTER TABLE "public"."gamification_missions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."gamification_outbox" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
