    "user_id" "uuid" NOT NULL,
    "action_type" "text" NOT NULL,
    "quantity" integer DEFAULT 1 NOT NULL,
    "source" "text" DEFAULT 'system_action'::"text" NOT NULL,
    "reference_id" "text",
    "idempotency_key" "text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "attempts" integer DEFAULT 0 NOT NULL,
    "max_attempts" integer DEFAULT 5 NOT NULL,
    "available_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "locked_at" timestamp with time zone,
    "worker_id" "text",
    "processed_event_id" "uuid",
    "processed_at" timestamp with time zone,
    "last_error" "text",
    "occurred_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "gamification_outbox_action_catalog_canonical_check" CHECK (("action_type" = ANY (ARRAY['call_made'::"text", 'message_sent'::"text", 'contact_made'::"text", 'visit_scheduled'::"text", 'visit_confirmed'::"text", 'meeting_scheduled'::"text", 'meeting_held'::"text", 'proposal_sent'::"text", 'sale_closed'::"text", 'contract_signed'::"text", 'lost_lead_recovered'::"text", 'lead_created'::"text", 'lead_created_manual'::"text", 'property_created'::"text", 'prospecting_report'::"text"]))),
    CONSTRAINT "gamification_outbox_attempts_canonical_check" CHECK ((("attempts" >= 0) AND (("max_attempts" >= 1) AND ("max_attempts" <= 20)))),
    CONSTRAINT "gamification_outbox_quantity_canonical_check" CHECK ((("quantity" >= 1) AND ("quantity" <= 100))),
    CONSTRAINT "gamification_outbox_status_canonical_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'processing'::"text", 'completed'::"text", 'skipped'::"text", 'dead'::"text"])))
);


