CREATE TABLE IF NOT EXISTS "public"."vista_integrations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "api_url" "text" NOT NULL,
    "api_key" "text",
    "is_active" boolean DEFAULT true NOT NULL,
    "import_inactive" boolean DEFAULT false NOT NULL,
    "last_sync_at" timestamp with time zone,
    "total_synced" integer DEFAULT 0 NOT NULL,
    "sync_log" "jsonb",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "api_key_secret_ref" "uuid" NOT NULL,
    "status" "text" DEFAULT 'connected'::"text" NOT NULL,
    "last_error" "text",
    "created_by" "uuid",
    CONSTRAINT "vista_integrations_api_key_write_only_check" CHECK (("api_key" IS NULL)),
    CONSTRAINT "vista_integrations_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'connected'::"text", 'syncing'::"text", 'error'::"text", 'disabled'::"text"]))),
    CONSTRAINT "vista_integrations_total_synced_check" CHECK (("total_synced" >= 0))
);


ALTER TABLE "public"."vista_integrations" OWNER TO "postgres";


COMMENT ON COLUMN "public"."vista_integrations"."api_key" IS 'Write-only compatibility input. A BEFORE trigger moves values to Vault and stores NULL.';



COMMENT ON COLUMN "public"."vista_integrations"."api_key_secret_ref" IS 'Reference to the encrypted Vista API key in Supabase Vault.';



CREATE OR REPLACE VIEW "public"."vista_integrations_service" WITH ("security_invoker"='true') AS
 SELECT "v"."id",
    "v"."organization_id",
    "v"."api_url",
    "secrets"."decrypted_secret" AS "api_key",
    "v"."is_active",
    "v"."import_inactive",
    "v"."status",
    "v"."last_sync_at",
    "v"."last_error",
    "v"."total_synced",
    "v"."sync_log",
    "v"."created_by",
    "v"."created_at",
    "v"."updated_at"
   FROM ("public"."vista_integrations" "v"
     JOIN "vault"."decrypted_secrets" "secrets" ON (("secrets"."id" = "v"."api_key_secret_ref")));


ALTER VIEW "public"."vista_integrations_service" OWNER TO "postgres";


COMMENT ON VIEW "public"."vista_integrations_service" IS 'Service-role-only Vista integration projection with the Vault secret decrypted at query time.';



