CREATE TABLE IF NOT EXISTS "public"."whatsapp_message_reactions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "session_id" "uuid" NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "target_message_id" "uuid",
    "target_provider_message_id" "text" NOT NULL,
    "provider_reaction_message_id" "text",
    "actor_jid" "text" NOT NULL,
    "actor_name" "text",
    "from_me" boolean DEFAULT false NOT NULL,
    "emoji" "text",
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "reacted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "removed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "whatsapp_message_reactions_actor_check" CHECK ((("length"("btrim"("actor_jid")) >= 1) AND ("length"("btrim"("actor_jid")) <= 320))),
    CONSTRAINT "whatsapp_message_reactions_state_check" CHECK (((("status" = 'active'::"text") AND ("emoji" IS NOT NULL) AND (("length"("emoji") >= 1) AND ("length"("emoji") <= 64)) AND ("removed_at" IS NULL)) OR (("status" = 'removed'::"text") AND ("removed_at" IS NOT NULL)))),
    CONSTRAINT "whatsapp_message_reactions_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'removed'::"text"]))),
    CONSTRAINT "whatsapp_message_reactions_target_provider_check" CHECK ((("length"("btrim"("target_provider_message_id")) >= 1) AND ("length"("btrim"("target_provider_message_id")) <= 512)))
);


ALTER TABLE "public"."whatsapp_message_reactions" OWNER TO "postgres";


COMMENT ON TABLE "public"."whatsapp_message_reactions" IS 'Private normalized WhatsApp reaction state keyed by target provider message and actor.';



CREATE TABLE IF NOT EXISTS "public"."whatsapp_message_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "name" "text" NOT NULL,
    "content" "text" NOT NULL,
    "category" "text" DEFAULT 'geral'::"text",
    "variables" "text"[] DEFAULT ARRAY[]::"text"[],
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."whatsapp_message_templates" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_messages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "conversation_id" "uuid" NOT NULL,
    "session_id" "uuid",
    "message_id" "text" NOT NULL,
    "content" "text",
    "message_type" "text" DEFAULT 'text'::"text",
    "from_me" boolean DEFAULT false NOT NULL,
    "status" "text" DEFAULT 'sent'::"text",
    "media_url" "text",
    "media_mime_type" "text",
    "sent_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "delivered_at" timestamp with time zone,
    "read_at" timestamp with time zone,
    "media_status" "text",
    "media_storage_path" "text",
    "media_error" "text",
    "media_size" bigint,
    "sender_jid" "text",
    "sender_name" "text",
    "client_message_id" "text",
    "remote_jid" "text",
    "reaction_to_message_id" "text",
    "reaction_emoji" "text",
    "reaction_sender_jid" "text",
    "reaction_sender_name" "text",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "received_at" timestamp with time zone DEFAULT "now"(),
    "organization_id" "uuid" NOT NULL,
    "lead_id" "uuid",
    "sender_user_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "provider_message_id" "text",
    "direction" "text" DEFAULT 'inbound'::"text" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL
)
WITH ("autovacuum_vacuum_scale_factor"='0.02', "autovacuum_analyze_scale_factor"='0.01', "autovacuum_vacuum_threshold"='1000', "autovacuum_analyze_threshold"='1000', toast."autovacuum_vacuum_scale_factor"='0.02', toast."autovacuum_vacuum_threshold"='1000');


ALTER TABLE "public"."whatsapp_messages" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_session_access" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "can_view" boolean DEFAULT true,
    "can_send" boolean DEFAULT true,
    "granted_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "only_leads_access" boolean DEFAULT false NOT NULL,
    "access_mode" "text" DEFAULT 'assigned_leads_only'::"text" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "can_read" boolean DEFAULT true NOT NULL,
    CONSTRAINT "whatsapp_session_access_access_mode_check" CHECK (("access_mode" = ANY (ARRAY['assigned_leads_only'::"text", 'team_leads'::"text", 'all_leads'::"text", 'full_inbox'::"text"]))),
    CONSTRAINT "whatsapp_session_access_mode_check" CHECK ((("access_mode" IS NULL) OR ("access_mode" = 'assigned_leads_only'::"text")))
);


ALTER TABLE "public"."whatsapp_session_access" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."whatsapp_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "instance_name" "text" NOT NULL,
    "instance_id" "text",
    "status" "text" DEFAULT 'disconnected'::"text" NOT NULL,
    "phone_number" "text",
    "profile_name" "text",
    "profile_picture" "text",
    "is_active" boolean DEFAULT true,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "display_name" "text",
    "last_connected_at" timestamp with time zone,
    "is_notification_session" boolean DEFAULT false,
    "provider" "text" DEFAULT 'evolution'::"text" NOT NULL,
    "advanced_settings" "jsonb" DEFAULT '{}'::"jsonb",
    "qr_code" "text",
    "last_error" "text",
    CONSTRAINT "whatsapp_sessions_provider_check" CHECK (("provider" = ANY (ARRAY['evolution'::"text", 'evolution_go'::"text"]))),
    CONSTRAINT "whatsapp_sessions_status_check" CHECK (("status" = ANY (ARRAY['disconnected'::"text", 'connecting'::"text", 'qr_ready'::"text", 'connected'::"text", 'error'::"text", 'disabled'::"text", 'deleted'::"text"])))
);


